function chapterEssentials({
  book,
  chapter,
  commentary,
  libraryResources,
}: {
  book: string;
  chapter: number;
  commentary: ChapterResourceRecommendation;
  libraryResources: ChapterResourceRecommendation[];
}): ChapterResourceRecommendation[] {
  const key = `${book.toLowerCase().replaceAll(" ", "-")}-${chapter}`;
  return [
    {
      id: `${key}-webster-1828`,
      kind: "Dictionary",
      title: "Webster's 1828 Dictionary",
      status: "available",
      note: "First stop for KJV word meanings and older English usage.",
    },
    {
      id: `${key}-strongs-starter`,
      kind: "Bible Tool",
      title: "Strong's Starter Word Study",
      status: "sample",
      note: "Reviewed starter entries connect common KJV words to simple Greek/Hebrew study panels while the full import remains under review.",
    },
    {
      id: `${key}-easton`,
      kind: "Dictionary",
      title: "Easton's Bible Dictionary",
      author: "M. G. Easton",
      status: "available",
      note: "Public-domain Bible dictionary resource for names, places, themes, and background study.",
    },
    {
      id: `${key}-smith`,
      kind: "Dictionary",
      title: "Smith's Bible Dictionary",
      author: "William Smith",
      status: "available",
      note: "Public-domain dictionary resource for historical and geographical background.",
    },
    {
      id: `${key}-nave`,
      kind: "Dictionary",
      title: "Nave's Topical Bible",
      author: "Orville J. Nave",
      status: "available",
      note: "Topical Bible help for tracing doctrines, subjects, and related verses.",
    },
    {
      id: `${key}-tsk`,
      kind: "Cross References",
      title: "Treasury of Scripture Knowledge",
      status: "sample",
      note: "Cross-reference structure is ready; reviewed samples display before full TSK import.",
    },
    {
      id: `${key}-manners-customs`,
      kind: "Bible Tool",
      title: "Bible Manners and Customs",
      status: "available",
      note: "Use reviewed public-domain background resources for culture, daily life, and historical setting.",
    },
    {
      id: `${key}-geography-chronology`,
      kind: "Bible Tool",
      title: "Bible Geography and Chronology",
      status: "available",
      note: "Place and timeline data connect chapters to locations, periods, and major Bible events.",
    },
    {
      id: `${key}-book-introduction`,
      kind: "Bible Introduction",
      title: `${book} Book Introduction`,
      status: "available",
      note: "Author, date, theme, key verse, outline, Christ in the book, and recommended resources are available from the chapter workflow.",
    },
    {
      id: `${key}-survey`,
      kind: "Bible Survey",
      title: "66-Book Bible Survey",
      status: "available",
      note: "Survey coverage gives every Bible book a consistent study entry for teaching and overview work.",
    },
    {
      id: `${key}-halley`,
      kind: "Bible Handbook",
      title: "Halley's Bible Handbook",
      author: "Henry H. Halley",
      status: "rights review",
      note: "Useful handbook candidate, but do not import until edition, copyright, and commercial-use rights are verified.",
      warning: "Use with discernment",
    },
    {
      id: `${key}-unger`,
      kind: "Bible Handbook",
      title: "Unger's Bible Handbook",
      author: "Merrill F. Unger",
      status: "rights review",
      note: "Modern handbook candidate for comparison only; do not import unless rights permit.",
      warning: "Use with discernment",
    },
    commentary,
    ...libraryResources,
  ];
}

function chapterRecommendations(
  book: string,
  chapters: number[],
  options: {
    commentaryForChapter: (chapter: number) => ChapterResourceRecommendation;
    libraryForChapter: (chapter: number) => ChapterResourceRecommendation[];
  },
) {
  return chapters.map((chapter) => ({
    book,
    chapter,
    recommendations: chapterEssentials({
      book,
      chapter,
      commentary: options.commentaryForChapter(chapter),
      libraryResources: options.libraryForChapter(chapter),
    }),
  }));
}

