function referenceImportId(row: TskCrossReferenceImportRow) {
  return `tsk-${row.verse_ref}-${row.target_ref}-${row.source}`
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

