function createEmptyPresentation(title = "Sunday Presentation"): PresentationEntry {
  const now = new Date().toISOString();
  return {
    id: makeId("presentation"),
    title,
    sermonId: "",
    lessonId: "",
    slideDeckSourceId: "",
    status: "Draft",
    themeId: "warm-bible-study",
    slides: [],
    groups: [],
    notes: "",
    targetMinutes: 30,
    createdAt: now,
    updatedAt: now,
    archived: false,
  };
}

function normalizePresentationEntry(entry: Partial<PresentationEntry>): PresentationEntry | null {
  if (!entry.id) return null;
  const now = new Date().toISOString();
  const rawStatus = entry.status ?? "Draft";
  const status: PresentationStatus = ["Draft", "Ready", "Archived"].includes(rawStatus) ? rawStatus as PresentationStatus : "Draft";
  const slides = Array.isArray(entry.slides) ? entry.slides.map(normalizeSermonSlide) : [];
  const slideIds = new Set(slides.map((slide) => slide.id));
  const groups = Array.isArray(entry.groups)
    ? entry.groups
        .filter((group): group is PresentationSlideGroup => Boolean(group?.id && group?.name))
        .map((group) => ({
          id: group.id,
          name: group.name,
          slideIds: Array.isArray(group.slideIds) ? group.slideIds.filter((id) => slideIds.has(id)) : [],
        }))
    : [];
  return {
    id: entry.id,
    title: entry.title ?? "Sunday Presentation",
    sermonId: entry.sermonId ?? "",
    lessonId: entry.lessonId ?? "",
    slideDeckSourceId: entry.slideDeckSourceId ?? "",
    status,
    themeId: sermonSlideThemeId(entry.themeId),
    slides,
    groups,
    notes: entry.notes ?? "",
    targetMinutes: Number(entry.targetMinutes) > 0 ? Number(entry.targetMinutes) : 30,
    createdAt: entry.createdAt ?? now,
    updatedAt: entry.updatedAt ?? now,
    archived: Boolean(entry.archived || status === "Archived"),
  };
}

function loadPresentationEntries(): PresentationEntry[] {
  if (typeof window === "undefined") return [];

  try {
    const raw = window.localStorage.getItem(PRESENTATION_ENTRIES_KEY);
    const parsed = raw ? JSON.parse(raw) as Partial<PresentationEntry>[] : [];
    return parsed.map(normalizePresentationEntry).filter((entry): entry is PresentationEntry => Boolean(entry));
  } catch {
    return [];
  }
}

function savePresentationEntries(entries: PresentationEntry[]) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(PRESENTATION_ENTRIES_KEY, JSON.stringify(entries));
}

function createPresentationSessionId() {
  return Math.random().toString(36).slice(2, 5).toUpperCase() + "-" + Math.random().toString(36).slice(2, 5).toUpperCase();
}

function createPresentationControllerId() {
  return `controller-${Math.random().toString(36).slice(2, 8)}-${Date.now().toString(36)}`;
}

function loadPresentationControllerId() {
  if (typeof window === "undefined") return createPresentationControllerId();
  const existing = window.localStorage.getItem(PRESENTATION_CONTROLLER_ID_KEY);
  if (existing) return existing;
  const nextId = createPresentationControllerId();
  window.localStorage.setItem(PRESENTATION_CONTROLLER_ID_KEY, nextId);
  return nextId;
}

function presentationRemoteStorageKey(sessionId: string) {
  return `${PRESENTATION_REMOTE_KEY_PREFIX}${sessionId.trim().toUpperCase()}`;
}

function presentationSessionExpiresAt(now = new Date()) {
  return new Date(now.getTime() + PRESENTATION_SESSION_DURATION_HOURS * 60 * 60 * 1000).toISOString();
}

function normalizePresentationControlMode(value: unknown): PresentationControlMode {
  return value === "approval" ? "approval" : "open";
}

function normalizePresentationController(value: Partial<PresentationController> | null | undefined): PresentationController | null {
  if (!value?.id) return null;
  const now = new Date().toISOString();
  const status: PresentationControllerStatus = value.status === "owner" || value.status === "approved" || value.status === "waiting" || value.status === "blocked" ? value.status : "waiting";
  return {
    id: String(value.id),
    name: value.name || "Controller",
    status,
    joinedAt: value.joinedAt || now,
    approvedAt: value.approvedAt || "",
    lastSeenAt: value.lastSeenAt || now,
  };
}

function normalizePresentationControllers(value: unknown): PresentationController[] {
  if (!Array.isArray(value)) return [];
  return value
    .map((item) => normalizePresentationController(item as Partial<PresentationController>))
    .filter((item): item is PresentationController => Boolean(item));
}

function presentationControllerStatusLabel(status: PresentationControllerStatus) {
  if (status === "owner") return "Owner";
  if (status === "approved") return "Approved";
  if (status === "blocked") return "Blocked";
  return "Waiting";
}

function isPresentationSessionExpired(state: Pick<PresentationRemoteState, "expiresAt" | "ended">) {
  return Boolean(state.expiresAt && Date.parse(state.expiresAt) < Date.now()) || state.ended;
}

function presentationConnectionLabel(isoDate: string) {
  if (!isoDate) return "Not connected yet";
  const ageSeconds = Math.max(0, Math.round((Date.now() - Date.parse(isoDate)) / 1000));
  if (ageSeconds < 20) return "Connected now";
  if (ageSeconds < 120) return `Seen ${ageSeconds}s ago`;
  return `Seen ${Math.round(ageSeconds / 60)}m ago`;
}

function normalizePresentationRemoteState(value: Partial<PresentationRemoteState> | null | undefined): PresentationRemoteState | null {
  if (!value?.sessionId) return null;
  const now = new Date().toISOString();
  const slides = Array.isArray(value.slides) ? value.slides.map(normalizeSermonSlide) : [];
  const slideIndex = Math.min(Math.max(0, Number(value.slideIndex) || 0), Math.max(0, slides.length - 1));
  const expiresAt = value.expiresAt ?? presentationSessionExpiresAt();
  const ended = Boolean(value.ended) || Date.parse(expiresAt) < Date.now();
  return {
    sessionId: value.sessionId.trim().toUpperCase(),
    presentationId: value.presentationId ?? "",
    presenterUserId: value.presenterUserId ?? "",
    title: value.title ?? "Presentation",
    themeId: sermonSlideThemeId(value.themeId),
    slides,
    slideIndex,
    blank: Boolean(value.blank),
    ended,
    controlMode: normalizePresentationControlMode(value.controlMode),
    controllerLocked: Boolean(value.controllerLocked),
    controllers: normalizePresentationControllers(value.controllers),
    lastControllerId: value.lastControllerId ?? "",
    displayLastSeenAt: value.displayLastSeenAt ?? "",
    expiresAt,
    targetMinutes: Number(value.targetMinutes) > 0 ? Number(value.targetMinutes) : 30,
    notes: value.notes ?? "",
    startedAt: value.startedAt ?? now,
    updatedAt: value.updatedAt ?? now,
  };
}

function loadPresentationRemoteState(sessionId: string): PresentationRemoteState | null {
  if (typeof window === "undefined" || !sessionId.trim()) return null;
  try {
    const raw = window.localStorage.getItem(presentationRemoteStorageKey(sessionId));
    return raw ? normalizePresentationRemoteState(JSON.parse(raw) as Partial<PresentationRemoteState>) : null;
  } catch {
    return null;
  }
}

function savePresentationRemoteState(state: PresentationRemoteState) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(presentationRemoteStorageKey(state.sessionId), JSON.stringify(state));
}

function presentationStateFromSessionRow(row: PresentationSessionRow): PresentationRemoteState {
  const slides = Array.isArray(row.slides) ? row.slides.map(normalizeSermonSlide) : [];
  const slideIndex = Math.min(Math.max(0, Number(row.current_slide_index) || 0), Math.max(0, slides.length - 1));
  const expiresAt = row.expires_at ?? presentationSessionExpiresAt();
  const ended = !row.is_active || Date.parse(expiresAt) < Date.now();
  return {
    sessionId: row.session_id,
    presentationId: row.presentation_id ?? "",
    presenterUserId: row.presenter_user_id ?? "",
    title: row.title ?? "Presentation",
    themeId: sermonSlideThemeId(row.theme_id),
    slides,
    slideIndex,
    blank: Boolean(row.is_blank),
    ended,
    controlMode: normalizePresentationControlMode(row.control_mode),
    controllerLocked: Boolean(row.controller_lock),
    controllers: normalizePresentationControllers(row.controllers),
    lastControllerId: row.last_controller_id ?? "",
    displayLastSeenAt: row.display_last_seen_at ?? "",
    expiresAt,
    targetMinutes: Number(row.target_minutes ?? 30) || 30,
    notes: row.notes ?? "",
    startedAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function presentationSessionRowFromState(state: PresentationRemoteState, userId?: string | null) {
  return {
    session_id: state.sessionId,
    presentation_id: state.presentationId || null,
    current_slide_index: state.slideIndex,
    is_blank: state.blank,
    is_active: !state.ended && Date.parse(state.expiresAt) >= Date.now(),
    presenter_user_id: state.presenterUserId || userId || null,
    control_mode: state.controlMode,
    controller_lock: state.controllerLocked,
    controllers: state.controllers,
    last_controller_id: state.lastControllerId || null,
    display_last_seen_at: state.displayLastSeenAt || null,
    expires_at: state.expiresAt,
    title: state.title || "Presentation",
    theme_id: state.themeId,
    slides: state.slides,
    target_minutes: state.targetMinutes,
    notes: state.notes,
    updated_at: state.updatedAt,
  };
}

function normalizeSavedChurchTheme(theme: Partial<SavedChurchTheme>): SavedChurchTheme | null {
  if (!theme.id || !theme.name) return null;
  const themeId = sermonSlideThemeId(theme.themeId);
  const imageSlot = typeof theme.imageSlot === "string" && theme.imageSlot in SERMON_SLIDE_IMAGE_SLOTS ? theme.imageSlot as SermonSlideImageSlotId : SERMON_SLIDE_THEMES[themeId].imageSlot;
  return {
    id: theme.id,
    name: theme.name,
    themeId,
    imageSlot,
    fontScale: ["Compact", "Normal", "Large"].includes(theme.fontScale ?? "") ? theme.fontScale as SermonSlideFontScale : SERMON_SLIDE_THEMES[themeId].fontScale,
    titleScale: ["Small", "Medium", "Large"].includes(theme.titleScale ?? "") ? theme.titleScale as SermonSlideTitleScale : "Medium",
    textPlacement: ["Center", "Left", "Bottom"].includes(theme.textPlacement ?? "") ? theme.textPlacement as SermonSlideTextPlacement : SERMON_SLIDE_THEMES[themeId].textPlacement,
    accentStyle: ["None", "Line", "Badge", "Panel"].includes(theme.accentStyle ?? "") ? theme.accentStyle as SermonSlideAccentStyle : SERMON_SLIDE_THEMES[themeId].accentStyle,
    backgroundIntensity: ["Soft", "Balanced", "Strong"].includes(theme.backgroundIntensity ?? "") ? theme.backgroundIntensity as SermonSlideBackgroundIntensity : "Balanced",
    showImageMotif: theme.showImageMotif ?? true,
    showTypeLabel: theme.showTypeLabel ?? false,
    showImageLabel: theme.showImageLabel ?? false,
    showFooterBranding: theme.showFooterBranding ?? false,
    createdAt: theme.createdAt ?? new Date().toISOString(),
  };
}

function loadSavedChurchThemes(): SavedChurchTheme[] {
  if (typeof window === "undefined") return [];

  try {
    const raw = window.localStorage.getItem(SERMON_CHURCH_THEMES_KEY);
    const parsed = raw ? JSON.parse(raw) as Partial<SavedChurchTheme>[] : [];
    return parsed.map(normalizeSavedChurchTheme).filter((theme): theme is SavedChurchTheme => Boolean(theme));
  } catch {
    return [];
  }
}

function saveSavedChurchThemes(themes: SavedChurchTheme[]) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(SERMON_CHURCH_THEMES_KEY, JSON.stringify(themes));
}

function savedChurchThemePatch(theme: SavedChurchTheme): Partial<SermonSlide> {
  return {
    imageSlot: theme.imageSlot,
    imageTheme: SERMON_SLIDE_IMAGE_SLOTS[theme.imageSlot].label,
    fontScale: theme.fontScale,
    titleScale: theme.titleScale,
    textPlacement: theme.textPlacement,
    accentStyle: theme.accentStyle,
    backgroundIntensity: theme.backgroundIntensity,
    backgroundStyle: "Theme",
    showImageMotif: theme.showImageMotif,
    showTypeLabel: theme.showTypeLabel,
    showImageLabel: theme.showImageLabel,
    showFooterBranding: theme.showFooterBranding,
  };
}

function bulletEachSentence(text: string) {
  return text
    .replace(/\s+/g, " ")
    .split(/(?<=[.!?])\s+/)
    .map((sentence) => sentence.trim())
    .filter(Boolean)
    .map((sentence) => `- ${sentence}`)
    .join("\n");
}

function buildSermonManuscript(entry: SermonEntry) {
  const sections = entry.sectionOrder?.length ? entry.sectionOrder : SERMON_SECTION_FIELDS;
  return sections
    .filter((section) => section !== "outline")
    .map((section) => entry[section])
    .filter((section) => section.trim())
    .join("\n\n");
}

function sermonWordCount(entry: SermonEntry) {
  return buildSermonManuscript(entry).trim().split(/\s+/).filter(Boolean).length;
}

function sermonLengthEstimate(entry: SermonEntry) {
  const words = sermonWordCount(entry);
  const minutes = Math.max(1, Math.round(words / 130));
  return { words, minutes };
}

function sermonSectionProgress(entry: SermonEntry) {
  return SERMON_SECTION_FIELDS.filter((section) => entry[section].trim()).length;
}

function sermonContentLines(text: string, limit = 8) {
  return text
    .split(/\n+|;|\u2022/)
    .map((line) => line.replace(/^[-*\d.IVXivx)\s]+/, "").trim())
    .filter(Boolean)
    .slice(0, limit);
}

function suggestedSermonImageSlot(entry: Pick<SermonEntry, "title" | "passage" | "theme" | "points" | "applications">): SermonSlideImageSlotId {
  const haystack = [entry.title, entry.passage, entry.theme, entry.points, entry.applications].join(" ").toLowerCase();
  return (SERMON_IMAGE_THEME_SUGGESTIONS.find((suggestion) => suggestion.terms.some((term) => haystack.includes(term)))?.slot ?? "open-bible") as SermonSlideImageSlotId;
}

function suggestedSermonImageTheme(entry: Pick<SermonEntry, "title" | "passage" | "theme" | "points" | "applications">) {
  return SERMON_SLIDE_IMAGE_SLOTS[suggestedSermonImageSlot(entry)].label;
}

function slidePresetPatch(themeId: SermonSlideThemeId): Partial<SermonSlide> {
  const theme = SERMON_SLIDE_THEMES[themeId] ?? SERMON_SLIDE_THEMES["classic-pulpit"];
  return {
    imageSlot: theme.imageSlot,
    imageTheme: SERMON_SLIDE_IMAGE_SLOTS[theme.imageSlot].label,
    fontScale: theme.fontScale,
    titleScale: "Medium",
    textPlacement: theme.textPlacement,
    accentStyle: theme.accentStyle,
    backgroundStyle: "Theme",
    backgroundIntensity: "Balanced",
    showImageMotif: true,
  };
}

function chunkScriptureText(text: string, maxLength = 460) {
  const lines = text.split(/\n+/).map((line) => line.trim()).filter(Boolean);
  const chunks: string[] = [];
  let current = "";
  lines.forEach((line) => {
    const candidate = current ? `${current}\n${line}` : line;
    if (candidate.length > maxLength && current) {
      chunks.push(current);
      current = line;
    } else {
      current = candidate;
    }
  });
  if (current) chunks.push(current);
  return chunks.length ? chunks : [text];
}

function formatScriptureSlideText(text: string, display: SermonSlideVerseDisplay) {
  return text
    .split(/\n+/)
    .map((line) => {
      const trimmed = line.trim();
      const match = trimmed.match(/^((?:[1-3]\s)?[A-Za-z ]+\s+\d+:\d+)\s+(.+)$/);
      if (!match) return trimmed;
      if (display === "Reference Only") return match[1];
      if (display === "Text Only") return match[2];
      return `${match[1]} ${match[2]}`;
    })
    .filter(Boolean)
    .join("\n");
}

function sermonSlideTemplatePatch(type: SermonSlideType): Partial<SermonSlide> {
  if (type === "Scripture") {
    return {
      layout: "Scripture Focus",
      fontScale: "Large",
      titleScale: "Medium",
      textPlacement: "Center",
      accentStyle: "Line",
      imageTheme: "Open Bible",
      imageSlot: "open-bible",
      backgroundIntensity: "Balanced",
    };
  }
  if (type === "Main Point") {
    return {
      layout: "Teaching Point",
      fontScale: "Normal",
      titleScale: "Large",
      textPlacement: "Left",
      accentStyle: "Badge",
      imageTheme: "Pulpit / Teaching",
      imageSlot: "pulpit",
      backgroundIntensity: "Balanced",
    };
  }
  if (type === "Quote") {
    return {
      layout: "Minimal",
      fontScale: "Normal",
      titleScale: "Small",
      textPlacement: "Center",
      accentStyle: "Panel",
      imageTheme: "Parchment / Simple Texture",
      imageSlot: "parchment",
      backgroundIntensity: "Soft",
    };
  }
  if (type === "Illustration") {
    return {
      layout: "Image Left",
      fontScale: "Normal",
      titleScale: "Medium",
      textPlacement: "Left",
      accentStyle: "Panel",
      imageTheme: "Quiet Study",
      imageSlot: "quiet-study",
      backgroundIntensity: "Balanced",
    };
  }
  if (type === "Application") {
    return {
      layout: "Two Column",
      fontScale: "Normal",
      titleScale: "Medium",
      textPlacement: "Left",
      accentStyle: "Line",
      imageTheme: "Light / Window",
      imageSlot: "light-window",
      backgroundIntensity: "Balanced",
    };
  }
  if (type === "Closing / Invitation") {
    return {
      layout: "Centered",
      fontScale: "Large",
      titleScale: "Large",
      textPlacement: "Center",
      accentStyle: "Line",
      imageTheme: "Cross",
      imageSlot: "cross",
      backgroundIntensity: "Strong",
    };
  }
  return {
    layout: "Centered",
    fontScale: "Normal",
    titleScale: "Large",
    textPlacement: "Center",
    accentStyle: "Line",
    imageTheme: "Open Bible",
    imageSlot: "open-bible",
    backgroundIntensity: "Balanced",
  };
}

function createSermonSlide(type: SermonSlideType, patch: Partial<SermonSlide> = {}): SermonSlide {
  const template = sermonSlideTemplatePatch(type);
  return normalizeSermonSlide({
    id: makeId("slide"),
    type,
    title: patch.title ?? type,
    subtitle: patch.subtitle ?? "",
    body: patch.body ?? "",
    bibleText: patch.bibleText ?? "",
    speakerNotes: patch.speakerNotes ?? "",
    backgroundStyle: patch.backgroundStyle ?? "Theme",
    imageTheme: patch.imageTheme ?? template.imageTheme ?? "Open Bible",
    imageSlot: patch.imageSlot ?? template.imageSlot ?? "open-bible",
    layout: patch.layout ?? template.layout ?? "Centered",
    fontScale: patch.fontScale ?? template.fontScale ?? "Normal",
    titleScale: patch.titleScale ?? template.titleScale ?? "Medium",
    textPlacement: patch.textPlacement ?? template.textPlacement ?? "Center",
    accentStyle: patch.accentStyle ?? template.accentStyle ?? "Line",
    verseDisplay: patch.verseDisplay ?? "Reference + Text",
    backgroundIntensity: patch.backgroundIntensity ?? template.backgroundIntensity ?? "Balanced",
    showImageMotif: patch.showImageMotif ?? true,
    showTypeLabel: patch.showTypeLabel ?? false,
    showImageLabel: patch.showImageLabel ?? false,
    showFooterBranding: patch.showFooterBranding ?? false,
  }, 0);
}

