function generateSermonSlides(entry: SermonEntry, scriptureText = ""): SermonSlide[] {
  const imageSlot = suggestedSermonImageSlot(entry);
  const imageTheme = SERMON_SLIDE_IMAGE_SLOTS[imageSlot].label;
  const preset = slidePresetPatch(entry.slideTheme);
  const scriptureChunks = scriptureText ? chunkScriptureText(scriptureText, 520) : [""];
  const pointLines = sermonContentLines(entry.points || entry.outline, 6);
  const quoteLines = sermonContentLines(entry.quotes, 3);
  const illustrationLines = sermonContentLines(entry.illustrations, 2);
  const applicationLines = sermonContentLines(entry.applications, 4);
  const slides: SermonSlide[] = [
    createSermonSlide("Title", {
      ...preset,
      title: entry.title || `${entry.kind} Title`,
      subtitle: [entry.passage, entry.theme].filter(Boolean).join(" - "),
      body: entry.seriesId ? "Series message" : "",
      speakerNotes: entry.introduction,
      imageTheme,
      imageSlot,
      layout: "Centered",
    }),
    ...scriptureChunks.map((chunk, index) => createSermonSlide("Scripture", {
      ...preset,
      title: scriptureChunks.length > 1 ? `${entry.passage || "Scripture Reading"} (${index + 1})` : entry.passage || "Scripture Reading",
      subtitle: "KJV",
      body: scriptureText ? "" : "Add or review the KJV text for this passage.",
      bibleText: chunk,
      speakerNotes: "Read the Scripture before the outline or commentary.",
      imageTheme: "Open Bible",
      imageSlot: "open-bible",
      layout: "Scripture Focus",
      fontScale: "Large",
      verseDisplay: "Reference + Text",
    })),
    ...pointLines.map((point, index) => createSermonSlide("Main Point", {
      ...preset,
      title: `Point ${index + 1}`,
      body: point,
      speakerNotes: point,
      imageTheme,
      imageSlot,
      layout: "Teaching Point",
    })),
    ...quoteLines.map((quote) => createSermonSlide("Quote", {
      ...preset,
      title: "Quote",
      body: quote,
      speakerNotes: "Verify the source and keep the quote secondary to Scripture.",
      imageTheme: "Parchment / Simple Texture",
      imageSlot: "parchment",
      layout: "Minimal",
    })),
    ...illustrationLines.map((illustration) => createSermonSlide("Illustration", {
      ...preset,
      title: "Illustration",
      body: illustration,
      speakerNotes: "Keep the illustration short and clearly tied to the passage.",
      imageTheme,
      imageSlot,
      layout: "Image Left",
    })),
    ...applicationLines.map((application, index) => createSermonSlide("Application", {
      ...preset,
      title: `Application ${index + 1}`,
      body: application,
      speakerNotes: "Move from explanation to obedience and prayer.",
      imageTheme,
      imageSlot,
      layout: "Two Column",
    })),
    createSermonSlide("Closing / Invitation", {
      ...preset,
      title: "Closing / Invitation",
      body: entry.invitation || entry.conclusion || "Close with Scripture-centered response.",
      speakerNotes: entry.conclusion,
      imageTheme,
      imageSlot,
      layout: "Centered",
    }),
  ];
  return slides.slice(0, 18);
}

function sermonSlideOutline(slides: SermonSlide[]) {
  return slides.map((slide, index) => [
    `${index + 1}. ${slide.type}: ${slide.title || "Untitled slide"}`,
    slide.subtitle ? `   Subtitle: ${slide.subtitle}` : "",
    slide.body ? `   Body: ${slide.body}` : "",
    slide.bibleText ? `   Scripture: ${slide.bibleText}` : "",
    slide.speakerNotes ? `   Notes: ${slide.speakerNotes}` : "",
  ].filter(Boolean).join("\n")).join("\n\n");
}

function presentationExportMarkdown(entry: PresentationEntry) {
  const theme = SERMON_SLIDE_THEMES[entry.themeId] ?? SERMON_SLIDE_THEMES["warm-bible-study"];
  return [
    `# ${entry.title || "Presentation"}`,
    "",
    `- Status: ${entry.status}`,
    `- Theme: ${theme.name}`,
    `- Target time: ${entry.targetMinutes} minutes`,
    `- Slides: ${entry.slides.length}`,
    `- Groups: ${entry.groups.length}`,
    "",
    "## Presentation Notes",
    entry.notes || "No notes yet.",
    "",
    "## Slide Outline",
    entry.slides.length ? sermonSlideOutline(entry.slides) : "No slides yet.",
    "",
    "## Export Foundation",
    "- PowerPoint export: available as a 16:9 widescreen MVP.",
    "- PDF export: use the print-ready preview and choose Save as PDF.",
    "- Remote control: later phase.",
  ].join("\n");
}

function suggestedSermonLibraryItems(items: SermonLibraryItem[], searchText: string) {
  const haystack = searchText.toLowerCase();
  if (!haystack.trim()) return [];
  return items
    .map((item) => {
      const terms = [
        item.topic,
        item.title,
        item.passage,
        item.source,
        item.recommendedUse,
        ...item.tags,
      ].map((term) => term.toLowerCase());
      const score = terms.reduce((total, term) => total + (term && haystack.includes(term) ? 2 : 0), 0)
        + item.tags.reduce((total, tag) => total + (haystack.includes(tag.toLowerCase()) ? 1 : 0), 0)
        + (haystack.includes(item.passage.toLowerCase()) ? 3 : 0);
      return { item, score };
    })
    .filter(({ score }) => score > 0)
    .sort((a, b) => b.score - a.score || a.item.title.localeCompare(b.item.title))
    .map(({ item }) => item)
    .slice(0, 3);
}

function smartSuggestionTerms(searchText: string) {
  return Array.from(
    new Set(
      searchText
        .toLowerCase()
        .replace(/[^a-z0-9\s]/g, " ")
        .split(/\s+/)
        .map((term) => term.trim())
        .filter((term) => term.length > 2),
    ),
  );
}

function scoreSmartSuggestion(text: string, terms: string[]) {
  const haystack = text.toLowerCase();
  if (!haystack.trim() || !terms.length) return 0;
  return terms.reduce((total, term) => total + (haystack.includes(term) ? 1 : 0), 0);
}

function parseSermonPassageReference(searchText: string) {
  const text = searchText.replace(/\s+/g, " ");
  const sortedBooks = [...bookOrder].sort((a, b) => b.length - a.length);
  for (const bookName of sortedBooks) {
    const escapedBook = bookName.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+");
    const chapterMatch = text.match(new RegExp(`\\b${escapedBook}\\s+(\\d+)(?::(\\d+))?`, "i"));
    if (chapterMatch) {
      return {
        book: bookName,
        chapter: Number(chapterMatch[1]),
        verse: chapterMatch[2] ? Number(chapterMatch[2]) : undefined,
        label: `${bookName} ${chapterMatch[1]}${chapterMatch[2] ? `:${chapterMatch[2]}` : ""}`,
      };
    }
    if (new RegExp(`\\b${escapedBook}\\b`, "i").test(text)) {
      return { book: bookName, chapter: undefined, verse: undefined, label: bookName };
    }
  }
  return null;
}

function suggestedSermonCommentaries(entries: CommentaryEntry[], searchText: string): SmartSermonSuggestion[] {
  const passage = parseSermonPassageReference(searchText);
  const terms = smartSuggestionTerms(searchText);
  return entries
    .map((entry) => {
      const referenceScore = passage
        ? (entry.book === passage.book ? 5 : 0) + (passage.chapter && entry.chapter === passage.chapter ? 8 : 0)
        : 0;
      const textScore = scoreSmartSuggestion([
        entry.author,
        entry.resource_title,
        entry.source_title ?? "",
        entry.recommended_use ?? "",
        entry.reference ?? "",
      ].join(" "), terms);
      return { entry, score: referenceScore + textScore };
    })
    .filter(({ score }) => score > 0)
    .sort((a, b) => b.score - a.score || a.entry.author.localeCompare(b.entry.author))
    .slice(0, 5)
    .map(({ entry }) => {
      const reference = entry.reference || `${entry.book} ${entry.chapter}`;
      const verseRange = entry.verse_start && entry.verse_end
        ? entry.verse_start === entry.verse_end ? `:${entry.verse_start}` : `:${entry.verse_start}-${entry.verse_end}`
        : "";
      return {
        id: `commentary-${entry.id}`,
        title: entry.author,
        subtitle: entry.resource_title,
        body: entry.entry_text,
        meta: `${reference}${verseRange} - ${entry.public_domain_status}`,
        actionText: "Add commentary connection",
        importLabel: `Commentary: ${entry.author}`,
        importBody: [
          `${entry.author}, ${entry.resource_title}`,
          `Reference: ${reference}${verseRange}`,
          entry.recommended_use ? `Use: ${entry.recommended_use}` : "",
          entry.entry_text,
        ].filter(Boolean).join("\n"),
      };
    });
}

function suggestedSermonLibraryResources(resources: LibraryResource[], searchText: string): SmartSermonSuggestion[] {
  const terms = smartSuggestionTerms(searchText);
  return resources
    .map((resource) => {
      const authorProfile = libraryAuthorProfileForName(resource.author);
      const score = scoreSmartSuggestion([
        resource.title,
        resource.author,
        resource.category,
        resource.collection,
        resource.description,
        resource.recommended_use,
        resource.perspective_notes,
        ...resource.resource_labels,
        authorProfile?.shortLabel ?? "",
        authorProfile?.commentary ?? "",
        authorProfile?.subjects.join(" ") ?? "",
        authorProfile?.recommendedReadingOrder.join(" ") ?? "",
      ].join(" "), terms);
      return { resource, score };
    })
    .filter(({ score, resource }) => score > 0 && !/do not import|permission needed/i.test(`${resource.rights_status} ${resource.public_domain_status}`))
    .sort((a, b) => b.score - a.score || a.resource.title.localeCompare(b.resource.title))
    .slice(0, 5)
    .map(({ resource }) => ({
      id: `library-${resource.slug}`,
      title: resource.title,
      subtitle: resource.author,
      body: resource.description || resource.recommended_use,
      meta: `${resource.category} - ${resource.public_domain_status}`,
      actionText: "Add book connection",
      importLabel: `Library: ${resource.title}`,
      importBody: [
        `${resource.title} by ${resource.author}`,
        `Category: ${resource.category}`,
        `Recommended use: ${resource.recommended_use || "Use as a supporting resource."}`,
        `Rights: ${resource.public_domain_status || resource.rights_status}`,
      ].join("\n"),
    }));
}

function suggestedSermonStudyPlaylists(playlists: StudyPlaylistTemplate[], searchText: string): SmartSermonSuggestion[] {
  const terms = smartSuggestionTerms(searchText);
  const scored = playlists
    .map((playlist) => {
      const score = scoreSmartSuggestion([
        playlist.title,
        playlist.description,
        ...playlist.items.map((item) => `${item.kind} ${item.label}`),
        ...playlist.repeatOptions,
      ].join(" "), terms);
      return { playlist, score };
    })
    .sort((a, b) => b.score - a.score || a.playlist.title.localeCompare(b.playlist.title));
  return scored
    .filter(({ score }) => score > 0)
    .concat(scored.filter(({ score }) => score === 0).slice(0, 2))
    .slice(0, 4)
    .map(({ playlist }) => {
      const totalMinutes = playlist.items.reduce((total, item) => total + item.minutes, 0);
      return {
        id: `playlist-${playlist.id}`,
        title: playlist.title,
        subtitle: `${playlist.items.length} items - about ${totalMinutes} minutes`,
        body: playlist.description,
        meta: playlist.items.map((item) => item.kind).join(" + "),
        actionText: "Add playlist connection",
        importLabel: `Study Playlist: ${playlist.title}`,
        importBody: [
          playlist.description,
          `Estimated time: ${totalMinutes} minutes`,
          ...playlist.items.map((item) => `- ${item.kind}: ${item.label} (${item.minutes} min)`),
        ].join("\n"),
      };
    });
}

function suggestedSermonPrayerConnections(entries: PrayerEntry[], searchText: string): SmartSermonSuggestion[] {
  const terms = smartSuggestionTerms(searchText);
  const scored = entries
    .filter((entry) => entry.answerStatus !== "Answered")
    .map((entry) => {
      const score = scoreSmartSuggestion([
        entry.name,
        entry.category,
        entry.request,
        entry.notes,
        entry.bibleVerse ?? "",
        entry.passage ?? "",
        entry.studyNote ?? "",
        entry.missionaryVerse ?? "",
        entry.promiseVerse ?? "",
      ].join(" "), terms);
      return { entry, score };
    })
    .sort((a, b) => b.score - a.score || b.entry.updatedAt.localeCompare(a.entry.updatedAt));
  return scored
    .filter(({ score }) => score > 0)
    .concat(scored.filter(({ score }) => score === 0).slice(0, 2))
    .slice(0, 4)
    .map(({ entry }) => ({
      id: `prayer-${entry.id}`,
      title: entry.name,
      subtitle: entry.category,
      body: entry.request,
      meta: entry.passage || entry.bibleVerse || entry.rotation || "Prayer connection",
      actionText: "Add prayer connection",
      importLabel: `Prayer: ${entry.name}`,
      importBody: [
        `Category: ${entry.category}`,
        `Request: ${entry.request}`,
        entry.passage ? `Passage: ${entry.passage}` : "",
        entry.bibleVerse ? `Verse: ${entry.bibleVerse}` : "",
        entry.notes ? `Notes: ${entry.notes}` : "",
      ].filter(Boolean).join("\n"),
    }));
}

function suggestedSermonJournalConnections(entries: JournalEntry[], searchText: string): SmartSermonSuggestion[] {
  const terms = smartSuggestionTerms(searchText);
  const scored = entries
    .map((entry) => {
      const score = scoreSmartSuggestion([
        entry.bibleReadingPassage,
        entry.selectedVerseRefs,
        entry.versePassage,
        entry.wordsToDefine,
        entry.verseSays,
        entry.verseMeans,
        entry.verseApplies,
        entry.prayerResponse,
        entry.teachingThought,
        entry.sourceLabel,
      ].join(" "), terms);
      return { entry, score };
    })
    .sort((a, b) => b.score - a.score || b.entry.updatedAt.localeCompare(a.entry.updatedAt));
  return scored
    .filter(({ score }) => score > 0)
    .concat(scored.filter(({ score }) => score === 0).slice(0, 2))
    .slice(0, 4)
    .map(({ entry }) => ({
      id: `journal-${entry.id}`,
      title: entry.versePassage || entry.selectedVerseRefs || entry.bibleReadingPassage || "Journal entry",
      subtitle: formatShortDate(entry.date),
      body: entry.teachingThought || entry.verseApplies || entry.verseMeans || entry.verseSays || "Saved Scripture journal entry.",
      meta: entry.sourceLabel || entry.sourceType,
      actionText: "Add journal connection",
      importLabel: `Journal: ${entry.versePassage || entry.date}`,
      importBody: [
        `Date: ${entry.date}`,
        entry.versePassage ? `Passage: ${entry.versePassage}` : "",
        entry.verseSays ? `Says: ${entry.verseSays}` : "",
        entry.verseMeans ? `Means: ${entry.verseMeans}` : "",
        entry.verseApplies ? `Applies: ${entry.verseApplies}` : "",
        entry.teachingThought ? `Teaching thought: ${entry.teachingThought}` : "",
      ].filter(Boolean).join("\n"),
    }));
}

function transcriptSentences(transcript: string) {
  return transcript
    .replace(/\s+/g, " ")
    .split(/(?<=[.!?])\s+/)
    .map((sentence) => sentence.trim())
    .filter((sentence) => sentence.length > 18);
}

function transcriptOutlineLines(transcript: string) {
  const lines = transcript
    .split(/\n+/)
    .map((line) => line.trim())
    .filter(Boolean);
  const explicitOutline = lines
    .filter((line) => /^(?:point|main point|i\.|ii\.|iii\.|iv\.|v\.|\d+[.)-])\s+/i.test(line))
    .map((line) => line.replace(/^(?:point|main point|i\.|ii\.|iii\.|iv\.|v\.|\d+[.)-])\s*/i, "").trim())
    .filter(Boolean);
  if (explicitOutline.length) return explicitOutline.slice(0, 6);
  return transcriptSentences(transcript).slice(0, 5);
}

function transcriptApplicationLines(transcript: string) {
  const applicationTerms = /\b(apply|application|obey|pray|believe|repent|witness|serve|trust|respond)\b/i;
  return transcriptSentences(transcript).filter((sentence) => applicationTerms.test(sentence)).slice(0, 4);
}

function sermonExtractorDraftPatch(transcript: string, entry: SermonEntry): Partial<SermonEntry> {
  const sentences = transcriptSentences(transcript);
  const outlineLines = transcriptOutlineLines(transcript);
  const applications = transcriptApplicationLines(transcript);
  return {
    outline: outlineLines.map((line, index) => `${index + 1}. ${line}`).join("\n"),
    introduction: entry.introduction || sentences[0] || "",
    points: outlineLines.join("\n"),
    applications: applications.join("\n"),
    conclusion: entry.conclusion || sentences.at(-1) || "",
    importedStudyNotes: [
      entry.importedStudyNotes,
      "## Sermon Extractor Transcript Import",
      "Transcript organized into a draft outline and slides. Review wording before teaching or preaching.",
      transcript.slice(0, 1800),
    ].filter(Boolean).join("\n\n"),
  };
}

function generateSlidesFromTranscript(entry: SermonEntry, transcript: string, scriptureText = "") {
  const patch = sermonExtractorDraftPatch(transcript, entry);
  const extractorEntry: SermonEntry = {
    ...entry,
    ...patch,
  };
  return generateSermonSlides(extractorEntry, scriptureText);
}

function sermonPlainText(entry: SermonEntry, series: SermonSeries | null) {
  return sermonExportMarkdown(entry, series)
    .replace(/^# /gm, "")
    .replace(/^## /gm, "\n")
    .replace(/^- /gm, "");
}

function sermonExportMarkdown(entry: SermonEntry, series: SermonSeries | null) {
  const length = sermonLengthEstimate(entry);
  return [
    `# ${entry.title || `${entry.kind} Draft`}`,
    "",
    `- Type: ${entry.kind}`,
    `- Passage: ${entry.passage || "Not set"}`,
    `- Theme: ${entry.theme || "Not set"}`,
    `- Series: ${series?.title ?? "None"}`,
    `- Status: ${entry.status}`,
    `- Target time: ${entry.targetMinutes} minutes`,
    `- Estimated length: ${length.minutes} minutes (${length.words} words)`,
    "",
    ...(entry.sectionOrder?.length ? entry.sectionOrder : SERMON_SECTION_FIELDS).flatMap((section) => [
      `## ${SERMON_SECTION_LABELS[section]}`,
      entry[section] || `No ${SERMON_SECTION_LABELS[section].toLowerCase()} yet.`,
      "",
    ]),
    "## Imported Study Notes",
    entry.importedStudyNotes || "No imported study notes yet.",
    "",
    "## Quotes",
    entry.quotes || "No quotes yet.",
    "",
	    "## Bulleted Manuscript",
	    entry.bulletManuscript || bulletEachSentence(buildSermonManuscript(entry)) || "No manuscript yet.",
	    "",
	    "## Sermon Slide Outline",
	    entry.slides.length ? sermonSlideOutline(entry.slides) : "No slides generated yet.",
	    "",
	  ].join("\n");
}

function sermonOutlineText(entry: SermonEntry) {
  return [
    entry.title || `${entry.kind} Draft`,
    entry.passage ? `Passage: ${entry.passage}` : "",
    entry.theme ? `Theme: ${entry.theme}` : "",
    "",
    "Outline",
    entry.outline || "No outline yet.",
    "",
    "Main Points",
    entry.points || "No main points yet.",
    "",
    "Conclusion",
    entry.conclusion || "No conclusion yet.",
  ].filter((line) => line !== "").join("\n");
}

function sermonPreachingNotesMarkdown(entry: SermonEntry) {
  const length = sermonLengthEstimate(entry);
  const manuscript = entry.bulletManuscript || bulletEachSentence(buildSermonManuscript(entry));
  return [
    `# ${entry.title || `${entry.kind} Preaching Notes`}`,
    "",
    `- Passage: ${entry.passage || "Not set"}`,
    `- Theme: ${entry.theme || "Not set"}`,
    `- Target time: ${entry.targetMinutes} minutes`,
    `- Estimated length: ${length.minutes} minutes (${length.words} words)`,
    "",
    "## At-A-Glance Outline",
    entry.outline || "No outline yet.",
    "",
    "## Preaching / Teaching Notes",
    manuscript || "No preaching notes yet.",
    "",
    "## Next Section Reminders",
    (entry.sectionOrder?.length ? entry.sectionOrder : SERMON_SECTION_FIELDS)
      .filter((section) => entry[section].trim())
      .map((section, index) => `${index + 1}. ${SERMON_SECTION_LABELS[section]}`)
      .join("\n") || "No sections ready yet.",
  ].join("\n");
}

function sermonPrintHtml(entry: SermonEntry, series: SermonSeries | null) {
  const markdown = sermonExportMarkdown({ ...entry, bulletManuscript: entry.bulletManuscript || bulletEachSentence(buildSermonManuscript(entry)) }, series);
  const body = markdown
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/^# (.*)$/gm, "<h1>$1</h1>")
    .replace(/^## (.*)$/gm, "<h2>$1</h2>")
    .replace(/^- (.*)$/gm, "<p class=\"bullet\">$1</p>")
    .replace(/\n\n/g, "<br />");
  return `<!doctype html><html><head><meta charset="utf-8"><title>${entry.title || "Sermon Notes"}</title><style>body{font-family:Georgia,serif;line-height:1.55;margin:48px;color:#1f211c}h1{font-size:32px}h2{margin-top:28px;border-bottom:1px solid #ddd;padding-bottom:6px}.bullet{font-size:22px;margin:14px 0;padding-left:18px;border-left:4px solid #78966d}@media print{body{margin:32px}.bullet{break-inside:avoid}}</style></head><body>${body}</body></html>`;
}

function defaultLibraryProgress(resource: Pick<LibraryResource, "slug" | "title" | "author">, fontSize = 20): LibraryProgress {
  const now = new Date().toISOString();
  return {
    slug: resource.slug,
    title: resource.title,
    author: resource.author,
    progress: 0,
    fontSize,
    lineSpacing: 1.72,
    readingWidth: "comfortable",
    theme: "sepia",
    readingGoalMinutes: 20,
    bookmarks: [],
    startedAt: now,
    updatedAt: now,
  };
}

function dateKey(value: string) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return date.toISOString().slice(0, 10);
}

function computeLibraryReadingStreak(progressValues: LibraryProgress[], completedValues: CompletedResource[]) {
  const activeDays = new Set([
    ...progressValues.map((progress) => dateKey(progress.updatedAt)),
    ...completedValues.map((completed) => dateKey(completed.completedAt)),
  ].filter(Boolean));
  if (!activeDays.size) return "0 days";

  let streak = 0;
  const cursor = new Date();
  for (;;) {
    const key = cursor.toISOString().slice(0, 10);
    if (!activeDays.has(key)) break;
    streak += 1;
    cursor.setDate(cursor.getDate() - 1);
  }

  if (streak === 0) return "0 days";
  return `${streak} day${streak === 1 ? "" : "s"}`;
}

function normalizeLibraryProgress(progress: Partial<LibraryProgress> & Pick<LibraryProgress, "slug" | "title" | "author">): LibraryProgress {
  const fallback = defaultLibraryProgress(progress);
  return {
    ...fallback,
    ...progress,
    progress: Math.min(100, Math.max(0, Number(progress.progress ?? fallback.progress))),
    fontSize: Math.min(28, Math.max(16, Number(progress.fontSize ?? fallback.fontSize))),
    lineSpacing: Math.min(2.2, Math.max(1.35, Number(progress.lineSpacing ?? fallback.lineSpacing))),
    readingWidth: progress.readingWidth ?? fallback.readingWidth,
    theme: progress.theme ?? fallback.theme,
    readingGoalMinutes: Math.min(180, Math.max(5, Number(progress.readingGoalMinutes ?? fallback.readingGoalMinutes))),
    bookmarks: Array.isArray(progress.bookmarks) ? progress.bookmarks : [],
    startedAt: progress.startedAt ?? fallback.startedAt,
    updatedAt: progress.updatedAt ?? fallback.updatedAt,
  };
}

function loadLibraryProgress(): LibraryProgressState {
  if (typeof window === "undefined") return {};

  try {
    const raw = window.localStorage.getItem(LIBRARY_PROGRESS_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as Record<string, LibraryProgress>;
    if (!parsed || typeof parsed !== "object") return {};
    return Object.fromEntries(
      Object.entries(parsed)
        .filter(([, progress]) => progress?.slug && progress?.title && progress?.author)
        .map(([slug, progress]) => [slug, normalizeLibraryProgress(progress)]),
    );
  } catch {
    return {};
  }
}

