function normalizeVoiceSettings(settings?: Partial<VoiceSettings>): VoiceSettings {
  const validProfileIds = new Set(VOICE_PROFILES.map((profile) => profile.id));
  const profileVoiceURIs = Object.fromEntries(
    Object.entries(settings?.profileVoiceURIs ?? {}).filter(([profileId, voiceURI]) =>
      validProfileIds.has(profileId as VoiceProfileId) && typeof voiceURI === "string" && voiceURI.trim(),
    ),
  ) as Partial<Record<VoiceProfileId, string>>;
  const profileRates = Object.fromEntries(
    Object.entries(settings?.profileRates ?? {}).filter(([profileId, rate]) =>
      validProfileIds.has(profileId as VoiceProfileId) && typeof rate === "number" && rate >= 0.5 && rate <= 2.5,
    ),
  ) as Partial<Record<VoiceProfileId, number>>;
  return {
    ...DEFAULT_VOICE_SETTINGS,
    ...settings,
    selectedVoiceURI: typeof settings?.selectedVoiceURI === "string" ? settings.selectedVoiceURI : "",
    favoriteVoiceURIs: Array.isArray(settings?.favoriteVoiceURIs) ? Array.from(new Set(settings.favoriteVoiceURIs.filter(Boolean))) : [],
    maleFavoriteVoiceURIs: Array.isArray(settings?.maleFavoriteVoiceURIs) ? Array.from(new Set(settings.maleFavoriteVoiceURIs.filter(Boolean))) : [],
    femaleFavoriteVoiceURIs: Array.isArray(settings?.femaleFavoriteVoiceURIs) ? Array.from(new Set(settings.femaleFavoriteVoiceURIs.filter(Boolean))) : [],
    hideNoveltyVoices: typeof settings?.hideNoveltyVoices === "boolean" ? settings.hideNoveltyVoices : DEFAULT_VOICE_SETTINGS.hideNoveltyVoices,
    activeProfile: validProfileIds.has(settings?.activeProfile as VoiceProfileId) ? settings!.activeProfile! : DEFAULT_VOICE_SETTINGS.activeProfile,
    profileVoiceURIs,
    profileRates,
  };
}

function loadVoiceSettings(): VoiceSettings {
  if (typeof window === "undefined") return DEFAULT_VOICE_SETTINGS;

  try {
    const raw = window.localStorage.getItem(VOICE_SETTINGS_KEY);
    if (!raw) return DEFAULT_VOICE_SETTINGS;
    return normalizeVoiceSettings(JSON.parse(raw) as Partial<VoiceSettings>);
  } catch {
    return DEFAULT_VOICE_SETTINGS;
  }
}

function saveVoiceSettings(settings: VoiceSettings) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(VOICE_SETTINGS_KEY, JSON.stringify(normalizeVoiceSettings(settings)));
}

function markBibleBookMasteryChapter(
  state: BibleBookMasteryState,
  bookName: string,
  chapterNumber: number,
  field: "readChapters" | "listenedChapters",
) {
  const current = normalizeBibleBookMasteryRecord(state[bookName]);
  const nextRecord = {
    ...current,
    [field]: Array.from(new Set([...current[field], chapterNumber])).sort((a, b) => a - b),
    updatedAt: new Date().toISOString(),
  };

  return {
    ...state,
    [bookName]: nextRecord,
  };
}

function loadBiblePlaylists(): BibleAudioPlaylist[] {
  const starters = defaultStudyPlaylists();
  if (typeof window === "undefined") return starters;

  try {
    const raw = window.localStorage.getItem(BIBLE_PLAYLISTS_KEY);
    if (!raw) return starters;
    const parsed = JSON.parse(raw) as BibleAudioPlaylist[];
    if (!Array.isArray(parsed) || !parsed.length) return starters;
    const merged = parsed.map((playlist) => {
      const starter = starters.find((candidate) => candidate.id === playlist.id);
      if (!starter) return playlist;
      const existingItemIds = new Set(playlist.items.map((item) => item.id));
      return {
        ...playlist,
        items: [...playlist.items, ...starter.items.filter((item) => !existingItemIds.has(item.id))],
      };
    });
    const existingIds = new Set(merged.map((playlist) => playlist.id));
    return [...merged, ...starters.filter((playlist) => !existingIds.has(playlist.id))];
  } catch {
    return starters;
  }
}

function saveBiblePlaylists(playlists: BibleAudioPlaylist[]) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(BIBLE_PLAYLISTS_KEY, JSON.stringify(playlists));
}

function playlistItemsMatch(a: BiblePlaylistItem, b: BiblePlaylistItem) {
  return (
    a.type === b.type &&
    (a.book ?? "") === (b.book ?? "") &&
    (a.chapter ?? 0) === (b.chapter ?? 0) &&
    (a.chapterEnd ?? 0) === (b.chapterEnd ?? 0) &&
    (a.verseStart ?? 0) === (b.verseStart ?? 0) &&
    (a.verseEnd ?? 0) === (b.verseEnd ?? 0) &&
    (a.resourceSlug ?? "") === (b.resourceSlug ?? "") &&
    a.label === b.label
  );
}

