function normalizedLibraryText(value: string) {
  return value
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/&/g, " and ")
    .replace(/\[[^\]]+\]/g, " ")
    .replace(/\bmicroform\b/g, " ")
    .replace(/\bfacsimile\b/g, " ")
    .replace(/\bfrom old catalog\b/g, " ")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function canonicalLibraryTitle(title: string) {
  const normalized = normalizedLibraryText(title)
    .replace(/\bvol(?:ume)?\s+[ivxlcdm0-9]+\b/g, " ")
    .replace(/\bvol\s*\d+\b/g, " ")
    .replace(/\bvolume\s*(?:one|two|three|four|five|six|seven|eight|nine|ten)\b/g, " ")
    .replace(/\b(?:volume|vol)\s+\d+\s+of\s+\d+\b/g, " ")
    .replace(/\b(?:volume|vol)\s+[ivxlcdm]+\s+of\s+[ivxlcdm]+\b/g, " ")
    .replace(/\b(?:part|book)\s+[ivxlcdm0-9]+\b/g, " ")
    .replace(/\bcomplete\b/g, " ")
    .replace(/\b\d+(st|nd|rd|th)?\s+series\b/g, " ")
    .replace(/\bno\s+\d+\b/g, " ")
    .replace(/\bnos\s+\d+(?:\s+\d+)*\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  const knownTitle = KNOWN_LIBRARY_WORK_TITLES.find((candidate) => normalized.includes(candidate));
  if (knownTitle) return knownTitle;

  return normalized
    .replace(/^(the|a|an)\s+/, "")
    .replace(/\s+(or|being|containing|with|and other|microform)\s+.*$/, "")
    .replace(/\s+/g, " ")
    .trim();
}

function canonicalLibraryAuthor(author: string) {
  const authorId = libraryAuthorIdFromName(author);
  if (["spurgeon", "ironside", "kelly", "darby", "grant", "gaebelein", "ryle", "meyer", "torrey", "moody", "bounds", "murray", "bunyan", "taylor"].includes(authorId)) {
    return authorId;
  }
  return normalizedLibraryText(author);
}

function libraryWorkKey(resource: Pick<LibraryResource, "title" | "author">) {
  return `${canonicalLibraryTitle(resource.title)}::${canonicalLibraryAuthor(resource.author)}`;
}

function strongerLibraryResource(current: LibraryResource, candidate: LibraryResource) {
  if (candidate.public_domain_status === "verified" && current.public_domain_status !== "verified") return candidate;
  if (candidate.source_url.includes("gutenberg.org") && !current.source_url.includes("gutenberg.org")) return candidate;
  if ((candidate.ocr_quality_score ?? 0) > (current.ocr_quality_score ?? 0)) return candidate;
  if (candidate.safe_for_quotation === true && current.safe_for_quotation !== true) return candidate;
  if ((candidate.word_count ?? 0) > (current.word_count ?? 0)) return candidate;
  return current;
}

function preferredLibraryWorkTitle(resources: LibraryResource[]) {
  const shortest = resources
    .map((resource) => resource.title.trim())
    .filter(Boolean)
    .sort((a, b) => normalizedLibraryText(a).length - normalizedLibraryText(b).length || a.localeCompare(b))[0];
  return shortest ?? resources[0]?.title ?? "Untitled Work";
}

function sortLibraryEditions(resources: LibraryResource[]) {
  return [...resources].sort((a, b) => {
    const aClean = a.source_url.includes("gutenberg.org") ? 1 : 0;
    const bClean = b.source_url.includes("gutenberg.org") ? 1 : 0;
    return (
      bClean - aClean ||
      (b.ocr_quality_score ?? 0) - (a.ocr_quality_score ?? 0) ||
      (b.word_count ?? 0) - (a.word_count ?? 0) ||
      a.title.localeCompare(b.title)
    );
  });
}

function groupLibraryWorks(resources: LibraryResource[]) {
  const byWork = new Map<string, LibraryResource[]>();

  for (const resource of resources) {
    const key = libraryWorkKey(resource);
    byWork.set(key, [...(byWork.get(key) ?? []), resource]);
  }

  return Array.from(byWork.entries()).map(([workKey, editions]) => {
    const sortedEditions = sortLibraryEditions(editions);
    const preferred = sortedEditions.reduce(strongerLibraryResource, sortedEditions[0]);
    return {
      ...preferred,
      work_key: workKey,
      work_title: preferredLibraryWorkTitle(sortedEditions),
      edition_count: sortedEditions.length,
      edition_group: sortedEditions,
    };
  });
}

function libraryWorkEditions(resource: LibraryResource, allResources: LibraryResource[]) {
  const key = resource.work_key ?? libraryWorkKey(resource);
  const explicitEditions = resource.edition_group ?? [];
  const matchingEditions = allResources.filter((candidate) => libraryWorkKey(candidate) === key);
  return sortLibraryEditions(matchingEditions.length ? matchingEditions : explicitEditions.length ? explicitEditions : [resource]);
}

function editionDescriptor(resource: LibraryResource, index: number) {
  const parts = [
    resource.source_url.includes("gutenberg.org") ? "Project Gutenberg" : resource.source_url.includes("archive.org") ? "Internet Archive scan" : "Verified source",
    resource.ocr_quality_label ?? ocrQualityLabel(resource),
    resource.year ? String(resource.year) : "",
  ].filter(Boolean);
  return `Edition ${index + 1}: ${parts.join(" · ")}`;
}

function libraryReadingMinutes(resource: LibraryResource) {
  if (!resource.word_count) return "Time unknown";
  return `${Math.max(1, Math.round(resource.word_count / 225))} min read`;
}

function libraryReadingHours(resource: LibraryResource) {
  const minutes = resource.reading_time_minutes ?? (resource.word_count ? Math.max(1, Math.round(resource.word_count / 225)) : null);
  if (!minutes) return "Reading time unknown";
  if (minutes < 60) return `${minutes} min read`;
  const hours = Math.floor(minutes / 60);
  const remainingMinutes = minutes % 60;
  return remainingMinutes ? `${hours} hr ${remainingMinutes} min read` : `${hours} hr read`;
}

function ocrQualityLabel(resource: LibraryResource) {
  if (resource.ocr_quality_label) return resource.ocr_quality_label;
  if (typeof resource.ocr_quality_score === "number") {
    if (resource.ocr_quality_score >= 90) return "Clean text";
    if (resource.ocr_quality_score >= 75) return "Usable OCR";
    return "Needs OCR review";
  }
  if (resource.resource_warnings.some((warning) => warning.toLowerCase().includes("ocr"))) return "Needs OCR review";
  return "Text quality not separately scored";
}

function ocrQualityScore(resource: LibraryResource) {
  if (typeof resource.ocr_quality_score === "number") return `${resource.ocr_quality_score}/100`;
  if (resource.resource_warnings.some((warning) => warning.toLowerCase().includes("ocr"))) return "Review needed";
  return "Not scored";
}

function resourceQualityLabels(resource: LibraryResource) {
  const labels = new Set<string>();
  const hasOcrWarning = resource.resource_warnings.some((warning) => warning.toLowerCase().includes("ocr"));

  if ((resource.ocr_quality_score ?? 100) >= 90 && !hasOcrWarning && resource.safe_for_quotation !== false && !resource.front_matter_cleanup_needed) {
    labels.add("Clean text");
  }

  labels.add("Safe for reading");

  if (hasOcrWarning || (resource.ocr_quality_score ?? 100) < 90) {
    labels.add("OCR spot-check needed");
  }

  if (resource.safe_for_quotation === false) {
    labels.add("Review before quoting");
  }

  if (resource.front_matter_cleanup_needed) {
    labels.add("Needs cleanup");
  }

  return Array.from(labels);
}

function resourceQualityLabelClass(label: string) {
  if (label === "Clean text" || label === "Safe for reading") return "bg-[var(--warm)] text-[var(--green)]";
  if (label === "Review before quoting" || label === "Needs cleanup") return "bg-amber-50 text-amber-800";
  return "bg-[var(--paper)] text-[var(--muted)]";
}

function audiobookDurationLabel(resource: LibraryResource, rate = 1) {
  if (resource.audiobook_duration) return resource.audiobook_duration;
  if (!resource.word_count) return "Duration unknown";
  return formatListeningDuration(listeningSecondsFromWordCount(resource.word_count, rate));
}

function audiobookMetadataForResource(resource: LibraryResource, rate = 1) {
  return {
    narrator: resource.audiobook_narrator || "Device text-to-speech",
    duration: audiobookDurationLabel(resource, rate),
    source: resource.audiobook_source || "Verified text read by browser/device voice",
    rightsStatus: resource.audiobook_rights_status || "Text rights verified; audio generated on this device",
    audioPath: resource.audiobook_audio_url || "Device speech synthesis",
    textSyncAvailable: resource.audiobook_text_sync_available ?? true,
  };
}

function libraryStudyText(resource: LibraryResource) {
  return [
    resource.title,
    resource.author,
    resource.category,
    resource.collection,
    resource.description,
    resource.recommended_use,
    resource.resource_labels.join(" "),
    resource.resource_warnings.join(" "),
  ].join(" ").toLowerCase();
}

function libraryAudienceLabels(resource: LibraryResource) {
  const text = libraryStudyText(resource);
  const labels = new Set<string>();

  if (text.includes("preach") || text.includes("teach") || text.includes("sermon") || text.includes("commentary")) labels.add("Teachers");
  if (text.includes("preach") || text.includes("illustration") || text.includes("application")) labels.add("Preachers");
  if (text.includes("prayer") || text.includes("pray") || text.includes("intercession")) labels.add("Prayer");
  if (text.includes("evangel") || text.includes("salvation") || text.includes("soul winner")) labels.add("Evangelism");
  if (text.includes("mission") || text.includes("missionary")) labels.add("Missions");
  if (text.includes("baptist") || text.includes("church history")) labels.add("Baptist history");
  if (text.includes("dictionary") || text.includes("topical") || text.includes("survey") || text.includes("handbook")) labels.add("Bible students");
  if (text.includes("christian living") || text.includes("devotional") || text.includes("discipleship")) labels.add("Christian growth");
  if (text.includes("kjv") || text.includes("textual") || text.includes("king james")) labels.add("Textual issues");

  if (!labels.size) labels.add("Serious readers");
  return Array.from(labels).slice(0, 4);
}

function relatedLibraryResourcesForResource(activeResource: LibraryResource, resources: LibraryResource[], limit = 10) {
  const activeAuthorId = libraryAuthorIdFromName(activeResource.author);
  const activeAudience = new Set(libraryAudienceLabels(activeResource));
  const activeText = libraryStudyText(activeResource);
  const importantTerms = [
    "john",
    "romans",
    "amos",
    "daniel",
    "revelation",
    "prayer",
    "preaching",
    "teaching",
    "missions",
    "baptist",
    "prophecy",
    "evangelism",
    "doctrine",
  ].filter((term) => activeText.includes(term));

  return resources
    .filter((resource) => resource.slug !== activeResource.slug)
    .map((resource) => {
      const relatedText = libraryStudyText(resource);
      const sharedAudience = libraryAudienceLabels(resource).filter((label) => activeAudience.has(label)).length;
      const sharedTerms = importantTerms.filter((term) => relatedText.includes(term)).length;
      const score =
        (libraryAuthorIdFromName(resource.author) === activeAuthorId ? 90 : 0) +
        (resource.collection === activeResource.collection ? 55 : 0) +
        (resource.category === activeResource.category ? 40 : 0) +
        (isCommentaryLikeResource(resource) === isCommentaryLikeResource(activeResource) ? 18 : 0) +
        sharedAudience * 14 +
        sharedTerms * 10 +
        Math.min(12, Math.round((resource.word_count ?? 0) / 25000));

      return { resource, score };
    })
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score || (b.resource.word_count ?? 0) - (a.resource.word_count ?? 0) || a.resource.title.localeCompare(b.resource.title))
    .map((item) => item.resource)
    .slice(0, limit);
}

function recommendedNextResourceReason(current: LibraryResource, next: LibraryResource) {
  if (libraryAuthorIdFromName(current.author) === libraryAuthorIdFromName(next.author)) return "Continue with the same author.";
  if (next.collection === current.collection) return "Another strong title from this collection.";
  if (next.category === current.category) return `More ${libraryCategoryLabel(current.category)} reading.`;
  if (isCommentaryLikeResource(next)) return "Compare this with another commentary voice.";
  return "A related resource for the same study path.";
}

function uniqueStudyCards(cards: Array<{ label: string; note: string }>, limit = 4) {
  const seen = new Set<string>();
  return cards.filter((card) => {
    const key = card.label.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, limit);
}

function relatedPassagesForLibraryResource(resource: LibraryResource) {
  const text = libraryStudyText(resource);
  const cards: Array<{ label: string; note: string }> = [];

  if (text.includes("john") || text.includes("gospel") || text.includes("salvation")) cards.push({ label: "John 3", note: "Gospel, new birth, and personal evangelism." });
  if (text.includes("roman") || text.includes("doctrine") || text.includes("faith")) cards.push({ label: "Romans 8", note: "Doctrine, assurance, and Christian living." });
  if (text.includes("prayer") || text.includes("intercession")) cards.push({ label: "Luke 11", note: "Prayer instruction and daily dependence." });
  if (text.includes("psalm") || text.includes("david") || text.includes("treasury")) cards.push({ label: "Psalm 23", note: "David, shepherd care, and devotional reading." });
  if (text.includes("mission") || text.includes("evangel")) cards.push({ label: "Acts 13", note: "Missionary calling and Gospel labor." });
  if (text.includes("preach") || text.includes("teach") || text.includes("study the bible")) cards.push({ label: "2 Timothy 2:15", note: "Bible study and approved work." });

  return uniqueStudyCards(cards.length ? cards : [
    { label: "John 3", note: "Start with a clear Gospel chapter." },
    { label: "Romans 8", note: "Use for doctrine, assurance, and application." },
  ], 3);
}

function sermonIdeasForLibraryResource(resource: LibraryResource) {
  const text = libraryStudyText(resource);
  const cards: Array<{ label: string; note: string }> = [];

  if (text.includes("prayer")) cards.push({ label: "Prayer emphasis", note: "Pull a quote, application, or burden for a prayer lesson." });
  if (text.includes("evangel") || text.includes("salvation")) cards.push({ label: "Gospel appeal", note: "Use as support for invitation, witness, or evangelism training." });
  if (text.includes("preach") || text.includes("illustration")) cards.push({ label: "Teaching illustration", note: "Save a short selection into sermon prep while reading." });
  if (text.includes("biography") || text.includes("mission") || text.includes("david")) cards.push({ label: "Life example", note: "Use the account as a careful historical or biographical illustration." });
  if (text.includes("doctrine") || text.includes("bible study")) cards.push({ label: "Lesson support", note: "Add definitions, outlines, or study observations to teaching notes." });

  return uniqueStudyCards(cards.length ? cards : [
    { label: "Sermon support", note: "Select text in the reader and add it to sermon notes, quotes, or illustrations." },
  ], 3);
}

function relatedThemesForLibraryResource(resource: LibraryResource, themes: StudyTheme[] = STUDY_THEMES) {
  const text = libraryStudyText(resource);
  return themes
    .map((theme) => {
      const terms = themeSearchTerms(theme).map((term) => term.toLowerCase()).filter((term) => term.length > 3);
      const score =
        (text.includes(theme.title.toLowerCase()) ? 60 : 0) +
        terms.filter((term) => text.includes(term)).length * 12 +
        theme.relatedBookTerms.filter((term) => text.includes(term.toLowerCase())).length * 16;
      return { theme, score };
    })
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score || a.theme.title.localeCompare(b.theme.title))
    .map((item) => item.theme)
    .slice(0, 6);
}

function relatedStudyPlaylistsForLibraryResource(resource: LibraryResource, templates: StudyPlaylistTemplate[] = STUDY_PLAYLIST_TEMPLATES) {
  const text = libraryStudyText(resource);
  return templates
    .map((template) => {
      const templateText = [
        template.title,
        template.description,
        ...template.items.map((item) => `${item.kind} ${item.label}`),
        ...template.repeatOptions,
      ].join(" ").toLowerCase();
      const resourceTerms = text.split(/[^a-z0-9]+/).filter((term) => term.length > 4);
      const score =
        (templateText.includes(resource.author.toLowerCase()) ? 45 : 0) +
        (templateText.includes(resource.category.toLowerCase()) ? 25 : 0) +
        resourceTerms.filter((term) => templateText.includes(term)).slice(0, 8).length * 8;
      return { template, score };
    })
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score || a.template.title.localeCompare(b.template.title))
    .map((item) => item.template)
    .slice(0, 4);
}

function isCommentaryLikeResource(resource: LibraryResource) {
  return libraryResourceMatches(resource, ["commentary", "expository", "exposition", "notes on", "homily"]);
}

function isEnglishSpeechVoice(voice: SpeechSynthesisVoice) {
  const lang = voice.lang.toLowerCase();
  return !lang || lang.startsWith("en");
}

function isNoveltySpeechVoice(voice: SpeechSynthesisVoice) {
  const name = voice.name.toLowerCase();
  const noveltyNames = [
    "albert",
    "bad news",
    "bahh",
    "bells",
    "boing",
    "bubbles",
    "cellos",
    "deranged",
    "good news",
    "grandma",
    "grandpa",
    "hysterical",
    "jester",
    "junior",
    "organ",
    "princess",
    "ralph",
    "superstar",
    "trinoids",
    "whisper",
    "wobble",
    "zarvox",
  ];
  return noveltyNames.some((novelty) => name.includes(novelty));
}

function speechVoiceCategory(voice: SpeechSynthesisVoice) {
  const lower = voice.name.toLowerCase();
  if (lower.includes("siri")) return "Apple Siri";
  if (["ava", "samantha", "allison", "susan", "victoria", "karen", "moira", "tessa", "veena", "zoe", "nicky"].some((name) => lower.includes(name))) return "Apple Female";
  if (["alex", "daniel", "fred", "oliver", "thomas", "tom", "aaron", "arthur", "reed", "evan"].some((name) => lower.includes(name))) return "Apple Male";
  if (lower.includes("female")) return "Female";
  if (lower.includes("male")) return "Male";
  return voice.localService ? "Device Voices" : "Browser Voices";
}

function speechVoiceGender(voice: SpeechSynthesisVoice): "male" | "female" | "unknown" {
  const category = speechVoiceCategory(voice);
  const lower = voice.name.toLowerCase();
  if (category.includes("Female") || lower.includes("female")) return "female";
  if (category.includes("Male") || lower.includes("male")) return "male";
  return "unknown";
}

function isAppleSpeechVoice(voice: SpeechSynthesisVoice) {
  return speechVoiceCategory(voice).startsWith("Apple") || voice.voiceURI.toLowerCase().includes("apple");
}

function voiceProfileById(profileId: VoiceProfileId) {
  return VOICE_PROFILES.find((profile) => profile.id === profileId) ?? VOICE_PROFILES[0];
}

function profileVoiceRank(voice: SpeechSynthesisVoice, profileId: VoiceProfileId) {
  const lower = voice.name.toLowerCase();
  const gender = speechVoiceGender(voice);
  const namedPriority: Record<VoiceProfileId, string[]> = {
    pastor: ["alex", "daniel", "oliver", "thomas", "aaron", "arthur", "reed"],
    teacher: ["samantha", "alex", "daniel", "ava", "allison", "karen"],
    scripture: ["alex", "daniel", "samantha", "moira", "oliver", "thomas"],
    audiobook: ["samantha", "alex", "daniel", "ava", "karen", "moira"],
    devotional: ["samantha", "moira", "karen", "tessa", "ava", "allison"],
    "fast-study": ["alex", "samantha", "daniel", "ava", "oliver"],
  };
  if (namedPriority[profileId].some((name) => lower.includes(name))) return 0;
  if ((profileId === "pastor" || profileId === "scripture") && gender === "male") return 1;
  if (profileId === "devotional" && gender === "female") return 1;
  if (isAppleSpeechVoice(voice)) return 2;
  if (voice.localService && !isNoveltySpeechVoice(voice)) return 3;
  return 4;
}

function isRecommendedSpeechVoice(voice: SpeechSynthesisVoice, profileId: VoiceProfileId) {
  return profileVoiceRank(voice, profileId) <= 2 && !isNoveltySpeechVoice(voice);
}

function voiceDisplayName(voice: SpeechSynthesisVoice) {
  return `${voice.name} · ${speechVoiceCategory(voice)}`;
}

function browserVoiceEnvironmentLabel() {
  if (typeof navigator === "undefined") return "Unknown browser";
  const agent = navigator.userAgent;
  const nav = navigator as Navigator & { userAgentData?: { brands?: Array<{ brand: string }> } };
  if (agent.includes("Edg/")) return "Microsoft Edge";
  if (agent.includes("Chrome/") && !agent.includes("Edg/")) return "Chrome or Chromium";
  if (agent.includes("Safari/") && !agent.includes("Chrome/")) return "Safari";
  if (agent.includes("Firefox/")) return "Firefox";
  return nav.userAgentData?.brands?.[0]?.brand ?? "Current browser";
}

function visibleSpeechVoices(voices: SpeechSynthesisVoice[], settings: VoiceSettings) {
  return voices.filter((voice) => isEnglishSpeechVoice(voice) && (!settings.hideNoveltyVoices || !isNoveltySpeechVoice(voice)));
}

function groupedSpeechVoices(voices: SpeechSynthesisVoice[], settings: VoiceSettings) {
  const used = new Set<string>();
  const groups: Array<{ category: string; voices: SpeechSynthesisVoice[] }> = [];
  const addGroup = (category: string, groupVoices: SpeechSynthesisVoice[]) => {
    const uniqueVoices = groupVoices.filter((voice) => {
      if (used.has(voice.voiceURI)) return false;
      used.add(voice.voiceURI);
      return true;
    });
    if (uniqueVoices.length) groups.push({ category, voices: uniqueVoices });
  };

  const profile = voiceProfileById(settings.activeProfile);
  addGroup("Favorite Voices", voices.filter((voice) => settings.favoriteVoiceURIs.includes(voice.voiceURI)));
  addGroup("Male Favorites", voices.filter((voice) => settings.maleFavoriteVoiceURIs.includes(voice.voiceURI)));
  addGroup("Female Favorites", voices.filter((voice) => settings.femaleFavoriteVoiceURIs.includes(voice.voiceURI)));
  addGroup(`Recommended: ${profile.label}`, voices.filter((voice) => isRecommendedSpeechVoice(voice, settings.activeProfile)));
  (["Apple Siri", "Apple Female", "Apple Male", "Female", "Male", "Device Voices", "Browser Voices"] as const).forEach((category) => {
    addGroup(category, voices.filter((voice) => speechVoiceCategory(voice) === category));
  });
  addGroup("Other Voices", voices);
  return groups;
}

function sortSpeechVoices(voices: SpeechSynthesisVoice[], settings: VoiceSettings) {
  const categoryOrder = new Map(
    ["Apple Siri", "Apple Female", "Apple Male", "Female", "Male", "Device Voices", "Browser Voices"].map((category, index) => [category, index]),
  );
  return [...voices].sort((a, b) => {
    const favoriteDifference =
      Number(!settings.favoriteVoiceURIs.includes(a.voiceURI)) - Number(!settings.favoriteVoiceURIs.includes(b.voiceURI)) ||
      Number(!settings.maleFavoriteVoiceURIs.includes(a.voiceURI)) - Number(!settings.maleFavoriteVoiceURIs.includes(b.voiceURI)) ||
      Number(!settings.femaleFavoriteVoiceURIs.includes(a.voiceURI)) - Number(!settings.femaleFavoriteVoiceURIs.includes(b.voiceURI));
    if (favoriteDifference) return favoriteDifference;
    const profileDifference = profileVoiceRank(a, settings.activeProfile) - profileVoiceRank(b, settings.activeProfile);
    if (profileDifference) return profileDifference;
    const noveltyDifference = Number(isNoveltySpeechVoice(a)) - Number(isNoveltySpeechVoice(b));
    if (noveltyDifference) return noveltyDifference;
    const categoryDifference = (categoryOrder.get(speechVoiceCategory(a)) ?? 99) - (categoryOrder.get(speechVoiceCategory(b)) ?? 99);
    if (categoryDifference) return categoryDifference;
    const localDifference = Number(b.localService) - Number(a.localService);
    if (localDifference) return localDifference;
    return a.name.localeCompare(b.name);
  });
}

function annotationLabel(type: LibraryAnnotationType) {
  if (type === "highlight") return "Highlight";
  if (type === "underline") return "Underline";
  if (type === "note") return "Note";
  if (type === "journal") return "Journal Note";
  return "Bookmark";
}

function annotationTone(type: LibraryAnnotationType) {
  if (type === "highlight") return "border-amber-200 bg-amber-50 text-amber-900";
  if (type === "underline") return "border-sky-200 bg-sky-50 text-sky-900";
  if (type === "note") return "border-emerald-200 bg-emerald-50 text-emerald-900";
  if (type === "journal") return "border-violet-200 bg-violet-50 text-violet-900";
  return "border-stone-200 bg-white text-[var(--ink)]";
}

function buildLibraryAnnotationsMarkdown(resource: LibraryResource, annotations: LibraryAnnotation[], progress?: LibraryProgress) {
  const sorted = [...annotations].sort((a, b) => a.location - b.location || a.createdAt.localeCompare(b.createdAt));
  return [
    `# ${resource.title} Reader Notes`,
    "",
    `Author: ${resource.author}`,
    `Category: ${libraryCategoryLabel(resource.category)}`,
    `Reading progress: ${formatPercent(progress?.progress ?? 0)}`,
    `Source: ${resource.source_url}`,
    "",
    "## Notes and Marks",
    "",
    ...(sorted.length
      ? sorted.flatMap((annotation) => [
          `### ${annotationLabel(annotation.type)} at ${annotation.location}%`,
          "",
          annotation.note ? `Name / note: ${annotation.note}` : "",
          annotation.text ? `> ${annotation.text}` : "",
          "",
          `Saved: ${new Date(annotation.createdAt).toLocaleString()}`,
          "",
        ])
      : ["No reader notes, highlights, underlines, or bookmarks saved yet.", ""]),
  ].filter((line) => line !== "").join("\n");
}

function libraryAuthorIdFromName(author: string) {
  const normalized = author.toLowerCase();
  if (normalized.includes("spurgeon")) return "spurgeon";
  if (normalized.includes("ironside")) return "ironside";
  if (normalized.includes("matthew henry")) return "matthew-henry";
  if (normalized.includes("barnes")) return "albert-barnes";
  if (normalized.includes("jamieson") || normalized.includes("fausset") || normalized.includes("brown")) return "jfb";
  if (normalized.includes("wesley")) return "john-wesley";
  if (normalized.includes("john gill") || normalized.includes("gill")) return "john-gill";
  if (normalized.includes("adam clarke") || normalized.includes("clarke")) return "adam-clarke";
  if (normalized.includes("ryle")) return "ryle";
  if (normalized.includes("moody")) return "moody";
  if (normalized.includes("bounds")) return "bounds";
  if (normalized.includes("murray")) return "murray";
  if (normalized.includes("torrey")) return "torrey";
  if (normalized.includes("bunyan")) return "bunyan";
  if (normalized.includes("hudson taylor") || normalized.includes("james hudson taylor")) return "taylor";
  if (normalized.includes("meyer")) return "meyer";
  if (normalized.includes("william kelly") || normalized.includes("kelly")) return "kelly";
  if (normalized.includes("f. w. grant") || normalized.includes("f w grant") || normalized.includes("frederick william grant")) return "grant";
  if (normalized.includes("clarence larkin") || normalized.includes("larkin")) return "larkin";
  if (normalized.includes("j. n. darby") || normalized.includes("darby")) return "darby";
  if (normalized.includes("gaebelein")) return "gaebelein";
  return normalized.replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

function libraryAuthorProfileForName(author: string) {
  const id = libraryAuthorIdFromName(author);
  return LIBRARY_AUTHOR_PROFILES.find((profile) => profile.id === id) ?? null;
}

function resourcesForAuthor(resources: LibraryResource[], profile: LibraryAuthorProfile) {
  return resources.filter((resource) => libraryAuthorIdFromName(resource.author) === profile.id);
}

function totalResourceReadingMinutes(resources: LibraryResource[]) {
  return resources.reduce((total, resource) => total + Math.max(1, Math.round((resource.word_count ?? 1200) / 225)), 0);
}

function readingMinutesLabel(minutes: number) {
  if (minutes >= 60) {
    const hours = Math.round(minutes / 60);
    return `${hours} hr${hours === 1 ? "" : "s"}`;
  }
  return `${minutes} min`;
}

function featuredTitlesForAuthor(resources: LibraryResource[], profile: LibraryAuthorProfile, limit = 4) {
  const authorResources = resourcesForAuthor(resources, profile);
  const preferred = profile.recommendedReadingOrder
    .map((title) => authorResources.find((resource) => resource.title.toLowerCase().includes(title.toLowerCase()) || title.toLowerCase().includes(resource.title.toLowerCase())))
    .filter(Boolean) as LibraryResource[];
  return Array.from(new Map([...preferred, ...authorResources].map((resource) => [resource.slug, resource])).values()).slice(0, limit);
}

function resourceMatchesAnyPattern(resource: LibraryResource, patterns: RegExp[]) {
  const text = libraryStudyText(resource);
  return patterns.some((pattern) => pattern.test(text));
}

function bestWorksForAuthor(resources: LibraryResource[], profile: LibraryAuthorProfile, limit = 8) {
  const preferred = featuredTitlesForAuthor(resources, profile, limit);
  const substantial = resources
    .filter((resource) => (resource.word_count ?? 0) >= 25000)
    .sort((a, b) => (b.word_count ?? 0) - (a.word_count ?? 0));
  return Array.from(new Map([...preferred, ...substantial, ...resources].map((resource) => [resource.slug, resource])).values()).slice(0, limit);
}

function shortWorksForAuthor(resources: LibraryResource[], limit = 8) {
  return resources
    .filter((resource) => {
      const wordCount = resource.word_count ?? 0;
      return wordCount > 0 && wordCount <= 18000;
    })
    .sort((a, b) => (a.word_count ?? 999999) - (b.word_count ?? 999999))
    .slice(0, limit);
}

function expositoryWorksForAuthor(resources: LibraryResource[], limit = 8) {
  return resources
    .filter((resource) => resourceMatchesAnyPattern(resource, [/commentary/, /exposition/, /expository/, /notes on/, /lectures on/, /gospel of/, /epistle/, /prophet/, /revelation/, /psalm/]))
    .slice(0, limit);
}

function devotionalWorksForAuthor(resources: LibraryResource[], limit = 8) {
  return resources
    .filter((resource) => resourceMatchesAnyPattern(resource, [/devotional/, /morning/, /evening/, /prayer/, /holiness/, /christian living/, /faith/, /grace/, /humility/, /surrender/]))
    .slice(0, limit);
}

function preachingTeachingWorksForAuthor(resources: LibraryResource[], limit = 8) {
  return resources
    .filter((resource) => resourceMatchesAnyPattern(resource, [/preach/, /sermon/, /teacher/, /teaching/, /illustration/, /students/, /soul.?winner/, /addresses/]))
    .slice(0, limit);
}

function resourcesForCollection(resources: LibraryResource[], collection: LibraryCollection) {
  return resources.filter((resource) => libraryResourceMatches(resource, collection.terms));
}

function resourcesForReadingPath(resources: LibraryResource[], path: ReadingPath) {
  const collectionTerms = path.collectionIds.flatMap((id) => libraryCollectionById(id)?.terms ?? []);
  const authorMatches = resources.filter((resource) => path.authorIds.includes(libraryAuthorIdFromName(resource.author)));
  const termMatches = resources.filter((resource) => libraryResourceMatches(resource, [...path.resourceTerms, ...collectionTerms]));

  return Array.from(new Map([...termMatches, ...authorMatches].map((resource) => [resource.slug, resource])).values())
    .sort((a, b) => {
      const aAuthorBoost = path.authorIds.includes(libraryAuthorIdFromName(a.author)) ? 0 : 1;
      const bAuthorBoost = path.authorIds.includes(libraryAuthorIdFromName(b.author)) ? 0 : 1;
      return aAuthorBoost - bAuthorBoost || (a.word_count ?? 999999) - (b.word_count ?? 999999);
    });
}

function primaryCollectionForResource(resource: LibraryResource) {
  return (
    LIBRARY_COLLECTIONS.find((collection) => libraryResourceMatches(resource, collection.terms)) ??
    LIBRARY_COLLECTIONS.find((collection) => collection.id === "study-helps")!
  );
}

function libraryCollectionById(id: string) {
  return LIBRARY_COLLECTIONS.find((collection) => collection.id === id)!;
}

function bibleStudyCollectionForBook(bookName: string) {
  return BIBLE_STUDY_COLLECTIONS.find((collection) => collection.book === bookName) ?? null;
}

function resourcesForBibleStudyCollection(resources: LibraryResource[], collection: BibleStudyCollection) {
  return resources
    .filter((resource) => libraryResourceMatches(resource, collection.relatedResourceTerms))
    .slice(0, 6);
}

function commentaryForBibleStudyCollection(entries: CommentaryEntry[], collection: BibleStudyCollection) {
  return entries.filter((entry) => entry.book === collection.book);
}

function fileExtension(fileName: string) {
  const parts = fileName.toLowerCase().split(".");
  return parts.length > 1 ? parts.pop() ?? "" : "";
}

function adminFileSupportLabel(fileName: string) {
  const extension = fileExtension(fileName);
  if (extension === "txt") return "TXT extraction ready";
  if (extension === "md" || extension === "markdown") return "Markdown extraction ready";
  if (extension === "docx") return "DOCX placeholder - text extraction not enabled yet";
  if (extension === "epub") return "EPUB placeholder - text extraction not enabled yet";
  if (extension === "pdf") return "PDF placeholder - text extraction not enabled yet";
  if (["mp3", "m4a", "wav"].includes(extension)) return "Audio file placeholder - upload/storage not enabled yet";
  if (["mp4", "mov", "webm"].includes(extension)) return "Video file placeholder - upload/storage not enabled yet";
  if (["png", "jpg", "jpeg", "webp"].includes(extension)) return "Cover image placeholder";
  if (extension === "zip") return "ZIP batch placeholder";
  return "Unsupported file type";
}

function adminFileCanExtractText(fileName: string) {
  const extension = fileExtension(fileName);
  return extension === "txt" || extension === "md" || extension === "markdown";
}

function detectCommentarySections(text: string, selectedBook: string) {
  const escapedBook = selectedBook.trim() ? escapeRegExp(selectedBook.trim()) : "[1-3]?\\s?[A-Z][a-z]+";
  const chapterPattern = new RegExp(`(?:^|\\n)\\s*(?:#{1,4}\\s*)?(?:chapter\\s+)?(${escapedBook})\\s+(\\d{1,3})(?::\\d{1,3})?\\b`, "gi");
  const matches = Array.from(text.matchAll(chapterPattern)).map((match) => `${match[1].replace(/\s+/g, " ").trim()} ${match[2]}`);
  const romanMatches = Array.from(text.matchAll(/(?:^|\n)\s*(?:#{1,4}\s*)?chapter\s+([ivxlcdm]+)\b/gi)).map((match) => `Chapter ${match[1].toUpperCase()}`);
  return Array.from(new Set([...matches, ...romanMatches])).slice(0, 24);
}

function detectDictionaryHeadwords(text: string) {
  const lines = text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  const headwords = lines
    .filter((line) => /^[A-Z][A-Z' -]{1,32}(?:,|\.)?\s/.test(line) || /^[A-Z][A-Z' -]{1,32}$/.test(line))
    .map((line) => line.replace(/[,.].*$/, "").trim())
    .filter((word) => word.length > 1 && word.length < 34);
  return Array.from(new Set(headwords)).slice(0, 24);
}

function detectAdminImportSections(resourceType: AdminResourceType, text: string, metadata: AdminImportMetadata) {
  if (!text.trim()) return [];
  if (resourceType === "Commentary") return detectCommentarySections(text, metadata.bibleBookCovered);
  if (resourceType === "Dictionary") return detectDictionaryHeadwords(text);
  const headings = Array.from(text.matchAll(/(?:^|\n)\s*(?:#{1,4}\s+|chapter\s+)([^\n]{3,80})/gi))
    .map((match) => match[1].trim())
    .filter(Boolean);
  return Array.from(new Set(headings)).slice(0, 12);
}

function adminImportRouteSummary(resourceType: AdminResourceType, sections: string[]) {
  if (resourceType === "Commentary") {
    return sections.length
      ? `Prepare ${sections.length} chapter commentary sections for review, then optionally add the full work to Library.`
      : "Commentary selected: add the Bible book covered and use clear chapter headings before review.";
  }
  if (resourceType === "Dictionary") {
    return sections.length
      ? `Prepare ${sections.length} detected headwords for dictionary review and keep source metadata attached.`
      : "Dictionary selected: headword detection will run after text is available.";
  }
  if (resourceType === "Library Book") return "Prepare for Library reader, author page, shelves, search, continue reading, and listening queue after review approval.";
  if (resourceType === "Audiobook") return "Prepare audiobook metadata, cover, narrator, duration, listening queue, and text-version link after rights review.";
  if (resourceType === "Bible Handbook") return "Prepare for Library reader and optional Book Introduction recommendations after review.";
  if (resourceType === "Bible Survey") return "Prepare for Library reader and book-level survey recommendations after review.";
  if (resourceType === "Devotional") return "Prepare for devotional Library shelves only after rights and doctrinal review.";
  if (resourceType === "Sermon Audio") return "Prepare sermon player metadata, preacher page, series, transcript link, and listening queue after permission review.";
  if (resourceType === "Sermon Video placeholder") return "Store video metadata only until hosting and permission are reviewed.";
  if (resourceType === "Sermon Transcript") return "Prepare transcript for sermon search, preacher pages, and teaching resources after review.";
  if (resourceType === "Sermon Series") return "Prepare a series shelf with ordered sermons, Scripture passages, and next-sermon flow after review.";
  if (resourceType === "KJV/Textual Issue Resource") return "Prepare for KJV/Textual Issues shelf with clear warnings and documented rights after review.";
  if (resourceType === "Baptist History") return "Prepare for Baptist History shelves and author pages after review.";
  if (resourceType === "Missions / Biography") return "Prepare for Missions, Biography, author pages, and listening queue after review.";
  return "Prepare for preaching/teaching shelves and lesson-prep recommendations after review.";
}

function validateAdminImport({
  fileName,
  resourceType,
  metadata,
  previewText,
  status,
  detectedSections,
}: {
  fileName: string;
  resourceType: AdminResourceType;
  metadata: AdminImportMetadata;
  previewText: string;
  status: ResourceImportStatus;
  detectedSections: string[];
}) {
  const errors: string[] = [];
  const warnings: string[] = [];
  const extension = fileExtension(fileName);

  if (!fileName) errors.push("Upload a file first.");
  if (!["txt", "md", "markdown", "docx", "epub", "pdf", "zip", "mp3", "m4a", "wav", "mp4", "mov", "webm", "png", "jpg", "jpeg", "webp"].includes(extension)) {
    errors.push("Supported upload types are TXT, Markdown, DOCX, EPUB, PDF, audio/video/cover placeholders, and ZIP placeholders.");
  }
  if (!metadata.title.trim()) errors.push("Title is required.");
  if (!metadata.author.trim()) errors.push("Author is required.");
  if (!metadata.category.trim()) errors.push("Category is required.");
  if (!metadata.sourceUrl.trim()) errors.push("Source URL or local source note is required.");
  if (!metadata.rightsStatus.trim()) errors.push("Rights status is required.");
  if (!metadata.doctrinalReviewStatus.trim()) errors.push("Doctrinal review status is required.");
  if (!metadata.recommendedUse.trim()) errors.push("Recommended use is required.");
  if ((extension === "pdf" || extension === "docx" || extension === "epub" || extension === "zip" || ["mp3", "m4a", "wav", "mp4", "mov", "webm"].includes(extension)) && status === "Verified") {
    errors.push("DOCX, EPUB, PDF, ZIP, audio, and video uploads cannot be marked verified until extraction/storage and review are implemented.");
  }
  if (!adminFileCanExtractText(fileName) && !previewText.trim()) warnings.push(`${extension.toUpperCase()} import is a placeholder. Store metadata now; extract text later.`);
  if (adminFileCanExtractText(fileName) && previewText.trim().length < 40) warnings.push("Extracted text is very short. Confirm the file imported correctly.");
  if (status === "Draft") warnings.push("Draft items stay in the admin queue and are hidden from the public Library.");
  if (status === "Verified" && !/public|permission|allowed|verified/i.test(metadata.rightsStatus)) {
    errors.push("Verified imports require clear public-domain, permission, or allowed-use rights notes.");
  }
  if (status === "Verified" && /needs review|unknown|unclear/i.test(metadata.rightsStatus)) {
    errors.push("Rights cannot still be unclear when status is verified.");
  }
  if (status === "Verified" && metadata.visibility !== "Public after review") {
    errors.push("Only public-after-review resources can be marked verified for public import.");
  }
  if (metadata.visibility === "Personal use only" && status !== "Personal Use Only") {
    errors.push("Personal-use uploads must use the Personal Use Only review status.");
  }
  if (resourceType === "Commentary") {
    if (!metadata.bibleBookCovered.trim()) errors.push("Commentary imports require the Bible book covered.");
    if (!detectedSections.length && previewText.trim()) warnings.push("No chapter headings detected yet. Add headings like John 3 or Chapter 3 before splitting.");
  }
  if (resourceType === "Dictionary" && previewText.trim() && !detectedSections.length) {
    warnings.push("No dictionary headwords detected yet. Use one headword per line or clear entry headings.");
  }
  if (resourceType.startsWith("Sermon")) {
    if (!metadata.preacher.trim()) errors.push("Sermon imports require a preacher.");
    if (!metadata.scripturePassage.trim()) errors.push("Sermon imports require a Scripture passage.");
    if (!metadata.topic.trim()) errors.push("Sermon imports require a topic.");
    if (status === "Verified" && !/permission|owned|public|allowed|licensed/i.test(metadata.rightsStatus)) {
      errors.push("Sermon media requires clear permission, ownership, license, or public-use rights before verification.");
    }
    warnings.push("Modern sermon audio/video must stay permission-needed unless publication rights are documented.");
  }
  if (resourceType === "Audiobook") {
    if (!metadata.narratorVoice.trim()) warnings.push("Audiobook metadata should include narrator or voice when available.");
    if (!metadata.duration.trim()) warnings.push("Audiobook metadata should include duration when available.");
    if (status === "Verified" && !metadata.audioFilePath.trim()) warnings.push("Verified audiobooks should point to a reviewed audio file or generated-device narration strategy.");
  }
  if (status === "Personal Use Only") warnings.push("Personal uploads must remain private to the signed-in user.");
  if (status === "Do Not Import") warnings.push("This item should remain blocked and must not appear in public Library search.");

  return { errors, warnings };
}

function loadAcquisitionStorage<T>(key: string, fallback: T[]): T[] {
  if (typeof window === "undefined") return fallback;
  try {
    const saved = window.localStorage.getItem(key);
    return saved ? JSON.parse(saved) : fallback;
  } catch {
    return fallback;
  }
}

function adminRecordRows<T extends { id: string }>(recordType: AdminAcquisitionRecordType, records: T[]) {
  return records.map((record) => ({
    record_type: recordType,
    record_key: record.id,
    payload: record,
  }));
}

function adminRecordsOfType<T>(rows: Array<{ record_type: string; payload: unknown }>, recordType: AdminAcquisitionRecordType): T[] {
  return rows.filter((row) => row.record_type === recordType).map((row) => row.payload as T);
}

