function LibraryResourceCard({
  resource,
  progress,
  listeningProgress,
  completed,
  onOpen,
  onOpenReader,
  onOpenAuthor,
  onAddToPlaylist,
}: {
  resource: LibraryResource;
  progress?: LibraryProgress;
  listeningProgress?: ListeningProgress;
  completed: boolean;
  onOpen: () => void;
  onOpenReader?: () => void;
  onOpenAuthor?: () => void;
  onAddToPlaylist?: () => void;
}) {
  const [coverFailed, setCoverFailed] = useState(false);
  const progressValue = completed ? 100 : progress?.progress ?? 0;
  const listeningValue = listeningProgress?.progress ?? 0;
  const coverSeed = resource.category.length + resource.title.length;
  const coverClass = coverSeed % 3 === 0 ? "from-[#334d41] to-[#9a7b3f]" : coverSeed % 3 === 1 ? "from-[#4f3d2d] to-[#476455]" : "from-[#263f5f] to-[#8a6d3b]";
  const showCoverImage = Boolean(resource.cover_image_url && !coverFailed);
  const audienceLabels = libraryAudienceLabels(resource);
  const displayTitle = resource.work_title ?? resource.title;
  const editionCount = resource.edition_count ?? resource.edition_group?.length ?? 1;
  const qualityLabels = resourceQualityLabels(resource).slice(0, 2);

  return (
    <article className="group flex h-full w-full flex-col overflow-hidden rounded-[1.35rem] border border-[var(--line)] bg-white text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-lg">
      <button className="block w-full text-left" onClick={onOpenReader ?? onOpen} type="button">
        <div className={`relative aspect-[3/4] min-h-[220px] overflow-hidden bg-gradient-to-br ${coverClass} p-5 text-white shadow-inner`}>
        {showCoverImage && (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            alt=""
            className="absolute inset-0 h-full w-full object-cover"
            loading="lazy"
            src={resource.cover_image_url ?? ""}
            onError={() => setCoverFailed(true)}
          />
        )}
        {showCoverImage && <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/20 to-black/5" />}
        <div className="absolute inset-x-6 top-5 h-px bg-white/30" />
        <div className="absolute left-5 top-5 rounded-full bg-white/15 px-2.5 py-1 text-[0.68rem] font-semibold uppercase tracking-[0.14em] text-white/85 backdrop-blur">
          {libraryCategoryLabel(resource.category)}
        </div>
        <div className="absolute inset-x-5 bottom-5">
          <h3 className="line-clamp-4 text-2xl font-semibold leading-7">{displayTitle}</h3>
          <p className="mt-4 line-clamp-1 text-sm font-semibold text-white/80">{resource.author}</p>
        </div>
        <div className="pointer-events-none absolute inset-x-4 bottom-4 translate-y-3 rounded-2xl bg-white/95 p-3 text-[var(--ink)] opacity-0 shadow-lg backdrop-blur transition duration-200 group-hover:translate-y-0 group-hover:opacity-100 group-focus-within:translate-y-0 group-focus-within:opacity-100">
          <p className="line-clamp-2 text-sm font-semibold leading-5">{displayTitle}</p>
          <p className="mt-1 text-xs font-semibold text-[var(--green)]">{libraryReadingMinutes(resource)} · {audienceLabels.slice(0, 2).join(", ")}</p>
          <p className="mt-2 line-clamp-2 text-xs leading-5 text-[var(--muted)]">{resource.recommended_use || resource.description}</p>
        </div>
        {completed && (
          <span className="absolute right-3 top-3 rounded-full bg-white/95 px-2.5 py-1 text-xs font-semibold text-[var(--green)]">
            Finished
          </span>
        )}
        {editionCount > 1 && (
          <span className="absolute right-3 top-12 rounded-full bg-white/95 px-2.5 py-1 text-xs font-semibold text-[var(--green)]">
            {editionCount} editions
          </span>
        )}
        </div>
        <div className="p-4">
        <h3 className="line-clamp-2 text-base font-semibold leading-6 text-[var(--ink)]">{displayTitle}</h3>
        <p className="mt-1 line-clamp-1 text-sm font-semibold text-[var(--green)]">{resource.author}</p>
        <div className="flex flex-wrap items-center gap-2">
          <p className="rounded-full bg-[var(--warm)] px-3 py-1 text-xs font-semibold text-[var(--muted)]">{libraryCategoryLabel(resource.category)}</p>
          <p className="rounded-full bg-[var(--paper)] px-3 py-1 text-xs font-semibold text-[var(--muted)]">{libraryReadingMinutes(resource)}</p>
          <p className="rounded-full bg-white px-3 py-1 text-xs font-semibold text-[var(--green)]">Read</p>
          <p className="rounded-full bg-white px-3 py-1 text-xs font-semibold text-[var(--green)]">Listen</p>
          {editionCount > 1 && (
            <p className="rounded-full bg-[var(--warm)] px-3 py-1 text-xs font-semibold text-[var(--green)]">{editionCount} editions</p>
          )}
          {audienceLabels.slice(0, 2).map((label) => (
            <p key={`resource-card-audience-${resource.slug}-${label}`} className="rounded-full bg-[var(--paper)] px-3 py-1 text-xs font-semibold text-[var(--green)]">{label}</p>
          ))}
        </div>
        <p className="mt-3 line-clamp-2 text-sm leading-6 text-[var(--scripture-ink)]">{resource.description}</p>
        <ResourceBadgeRow labels={resource.resource_labels.slice(0, 3)} warnings={resource.resource_warnings.slice(0, 2)} compact />
        {qualityLabels.length > 0 && (
          <div className="mt-3 rounded-2xl border border-[var(--line)] bg-[var(--paper)] px-3 py-2">
            <p className="text-[0.66rem] font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">Text quality</p>
            <div className="mt-2 flex flex-wrap gap-1.5">
              {qualityLabels.map((label) => (
                <span key={`resource-card-quality-${resource.slug}-${label}`} className={`rounded-full px-2.5 py-1 text-[0.68rem] font-semibold ${resourceQualityLabelClass(label)}`}>
                  {label}
                </span>
              ))}
            </div>
          </div>
        )}
        <div className="mt-4 space-y-2">
          <div>
            <div className="flex items-center justify-between text-xs font-semibold text-[var(--muted)]">
              <span>Reading</span>
              <span>{formatPercent(progressValue)}</span>
            </div>
            <div className="mt-1 h-2 rounded-full bg-[var(--warm)]">
              <div className="h-2 rounded-full bg-[var(--green)]" style={{ width: formatPercent(progressValue) }} />
            </div>
          </div>
          {listeningValue > 0 && (
            <div>
              <div className="flex items-center justify-between text-xs font-semibold text-[var(--muted)]">
                <span>Listening</span>
                <span>{formatPercent(listeningValue)}</span>
              </div>
              <div className="mt-1 h-2 rounded-full bg-[var(--warm)]">
                <div className="h-2 rounded-full bg-[var(--gold)]" style={{ width: formatPercent(listeningValue) }} />
              </div>
            </div>
          )}
        </div>
        </div>
      </button>
      <div className="mt-auto border-t border-[var(--line)] bg-[var(--paper)] p-3">
        <div className="grid grid-cols-3 gap-2">
          <button
            className="inline-flex items-center justify-center gap-2 rounded-full bg-[var(--green)] px-3 py-2 text-xs font-semibold text-white"
            onClick={onOpenReader ?? onOpen}
            type="button"
          >
            <BookOpen size={14} />
            Read
          </button>
          <button
            className="inline-flex items-center justify-center gap-2 rounded-full bg-white px-3 py-2 text-xs font-semibold text-[var(--green)] disabled:opacity-50"
            disabled={!onOpenReader}
            onClick={onOpenReader}
            type="button"
          >
            <Headphones size={14} />
            Listen
          </button>
          <button
            className="inline-flex items-center justify-center gap-2 rounded-full bg-white px-3 py-2 text-xs font-semibold text-[var(--green)] disabled:opacity-50"
            disabled={!onOpenAuthor}
            onClick={onOpenAuthor}
            type="button"
          >
            <Users size={14} />
            Author
          </button>
        </div>
        {onAddToPlaylist && (
          <button
            className="mt-2 inline-flex w-full items-center justify-center gap-2 rounded-full bg-white px-3 py-2 text-xs font-semibold text-[var(--green)]"
            onClick={onAddToPlaylist}
            type="button"
          >
            <ListMusic size={14} />
            Add to Playlist
          </button>
        )}
      </div>
    </article>
  );
}

function ResourceBadgeRow({
  labels,
  warnings,
  compact = false,
}: {
  labels: string[];
  warnings: string[];
  compact?: boolean;
}) {
  const visibleLabels = labels.filter(Boolean);
  const visibleWarnings = warnings.filter(Boolean);
  if (!visibleLabels.length && !visibleWarnings.length) return null;

  return (
    <div className={`${compact ? "mt-3" : "mt-4"} flex flex-wrap gap-2`}>
      {visibleLabels.map((label) => (
        <span
          key={`resource-label-${label}`}
          className="rounded-full bg-[var(--paper)] px-3 py-1 text-xs font-semibold text-[var(--green)]"
        >
          {label}
        </span>
      ))}
      {visibleWarnings.map((warning) => (
        <span
          key={`resource-warning-${warning}`}
          className="rounded-full bg-[var(--highlight)] px-3 py-1 text-xs font-semibold text-[var(--ink)]"
        >
          {warning}
        </span>
      ))}
    </div>
  );
}

function libraryCategoryLabel(category: string) {
  const labels: Record<string, string> = {
    "Preaching/teaching": "Preaching & Teaching",
    "Fiction/classics": "Classics",
    "Christian life": "Christian Living",
    "Baptist history": "Baptist History",
    "Bible study helps": "Bible Handbooks",
    "KJV/Textual Issues": "KJV / Textual Issues",
  };

  return labels[category] ?? category;
}

function PassageGuideScreen({
  book,
  chapter,
  verses,
  analysis,
  connections,
  background,
  crossReferences,
  commentaryEntries,
  keyVerses,
  recommendedResources,
  libraryResources,
  bookIntroduction,
  activeThemes,
  notes,
  memoryVerse,
  versesByRef,
  onBack,
  onOpenReference,
  onOpenBookIntroduction,
  onOpenLibraryResource,
  onOpenPersonStudy,
  onOpenThemeExplorer,
  onListenCommentary,
  onAddCommentaryToPlaylist,
}: {
  book: string;
  chapter: number;
  verses: BibleVerse[];
  analysis: ChapterStudyAnalysis;
  connections: ActiveChapterConnections;
  background: ActiveBibleBackground;
  crossReferences: CrossReference[];
  commentaryEntries: CommentaryEntry[];
  keyVerses: string[];
  recommendedResources: ChapterResourceRecommendation[];
  libraryResources: LibraryResource[];
  bookIntroduction: BookIntroduction | null;
  activeThemes: StudyTheme[];
  notes: Array<[string, UserNote[]]>;
  memoryVerse: ScriptureMemoryItem | null;
  versesByRef: Map<string, BibleVerse>;
  onBack: () => void;
  onOpenReference: (targetRef: string) => void;
  onOpenBookIntroduction: () => void;
  onOpenLibraryResource: (slug: string) => void;
  onOpenPersonStudy: (personId: string) => void;
  onOpenThemeExplorer: () => void;
  onListenCommentary: () => void;
  onAddCommentaryToPlaylist: () => void;
}) {
  const firstVerse = verses[0];
  const passage = `${book} ${chapter}`;
  const [packExportMessage, setPackExportMessage] = useState("");
  const displayKeyVerses = useMemo(
    () => keyVerses.length ? keyVerses : firstVerse ? [firstVerse.ref] : [],
    [firstVerse, keyVerses],
  );
  const exportData = useMemo<TeachingNotesExportData | null>(() => {
    if (!firstVerse) return null;
    return {
      book,
      chapter,
      bookIntroduction,
      keyVerses: displayKeyVerses,
      analysis,
      connections,
      background,
      crossReferences,
      commentaryEntries,
      notes,
      memoryVerse,
      fallbackMemoryVerse: firstVerse,
      recommendedResources,
      versesByRef,
    };
  }, [
    analysis,
    book,
    bookIntroduction,
    chapter,
    commentaryEntries,
    connections,
    background,
    crossReferences,
    displayKeyVerses,
    firstVerse,
    memoryVerse,
    notes,
    recommendedResources,
    versesByRef,
  ]);
  const teachingSummary = exportData ? teachingWorkspaceSummary(exportData) : null;
  const lessonOutlineSections = exportData ? buildLessonOutline(exportData, EMPTY_TEACHER_NOTES) : [];
  const chapterStudyPackMarkdown = exportData ? buildChapterStudyPackMarkdown(exportData) : "";
  const visibleCrossReferences = crossReferences.slice(0, 12);
  const commentaryAuthors = Array.from(new Set(commentaryEntries.map((entry) => entry.author))).sort();
  const commentaryRecommendation = buildCommentaryRecommendation(commentaryEntries);
  const commentaryConsensus = commentaryComparisonInsights(commentaryEntries);
  const passageConnections = PASSAGE_GUIDE_CONNECTIONS.filter((connection) => connection.book === book && connection.chapter === chapter);
  const topWords = analysis.repeatedWords.slice(0, 6);
  const guideDictionaryEntries = Array.from(
    new Map(
      topWords
        .map((item) => findDictionaryEntry(item.word))
        .filter((entry) => entry.found)
        .map((entry) => [entry.lookupWord, entry]),
    ).values(),
  );
  const guideStrongEntries = topWords
    .map((item) => strongsMvpEntries[normalizeLookupWord(item.word)])
    .filter((entry): entry is StrongMvpEntry => Boolean(entry))
    .slice(0, 6);
  const startHereCommentary = commentaryRecommendation.primary?.author ?? commentaryAuthors[0] ?? "No reviewed commentary yet";
  const startHereResources = recommendedResources.filter((resource) => resource.status === "available" || resource.resourceSlug).slice(0, 3);
  const bestResources = bestChapterResources(recommendedResources, commentaryEntries);
  const studyQuestions = passageStudyQuestions({ passage, keyVerses: displayKeyVerses, topWords, connections, commentaryAuthors });
  const teachingIllustrations = passageTeachingIllustrationPrompts({ passage, topWords, connections });
  const commentaryOrder = commentaryProfilesForEntries(commentaryEntries);
  const commentaryCenterAuthors = ["Matthew Henry", "Jamieson-Fausset-Brown", "Albert Barnes", "Adam Clarke", "John Wesley", "John Gill", "H. A. Ironside", "G. Campbell Morgan"];
  const availableCommentaryAuthors = new Set(commentaryAuthors);
  const commentaryCenterProfiles = commentaryCenterAuthors.map((author) => ({
    author,
    profile: commentaryGuideProfileFor(author),
    available: availableCommentaryAuthors.has(author),
    entries: commentaryEntries.filter((entry) => entry.author === author).length,
  }));
  const relatedBooks = relatedLibraryResourcesForPassage(recommendedResources, libraryResources);
  const summaryBody = bookIntroduction
    ? `${bookIntroduction.overview.theme} ${bookIntroduction.overview.purpose}`
    : connections.themes.length
      ? `Reviewed themes for ${passage}: ${connections.themes.slice(0, 4).join(", ")}.`
      : `A one-scroll guide for ${passage} using reviewed study data already loaded in the app.`;
  const sections = [
    ["passage-scorecard", "Scorecard"],
    ["passage-start-here", "Start Here"],
    ["passage-best-resources", "Best Resources"],
    ["passage-themes", "Themes"],
    ["passage-study-pack", "Study Pack"],
    ["passage-background", "Background"],
    ["passage-culture", "Culture"],
    ["passage-questions", "Questions"],
    ["passage-illustrations", "Illustrations"],
    ["passage-summary", "Summary"],
    ["passage-key-verses", "Key Verses"],
    ["passage-repeated-words", "Repeated Words"],
    ["passage-word-tools", "Word Tools"],
    ["passage-commentary-order", "Commentary Order"],
    ["passage-commentary", "Commentary"],
    ["passage-parallels", "Parallels"],
    ["passage-cross-references", "Cross References"],
    ["passage-people", "People"],
    ["passage-places", "Places"],
    ["passage-timeline", "Timeline"],
    ["passage-types", "Types"],
    ["passage-prophecies", "Prophecy"],
    ["passage-related-books", "Related Books"],
    ["passage-sermons", "Sermons"],
    ["passage-resources", "Resources"],
    ["passage-outline", "Teaching Outline"],
  ];

  if (!firstVerse) {
    return (
      <div className="p-4 md:p-8">
        <EmptyState title="Passage Guide not ready" body="This chapter is not available in the local KJV data yet." />
      </div>
    );
  }

  return (
    <div className="space-y-4 p-4 pb-36 md:p-8 md:pb-10">
      <div className="sticky top-[104px] z-10 -mx-4 border-b border-[var(--line)] bg-[var(--paper)]/95 px-4 pb-3 pt-2 backdrop-blur md:top-0 md:mx-0 md:rounded-2xl md:border md:px-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <button
            className="inline-flex items-center gap-2 rounded-full border border-[var(--line)] bg-white px-4 py-2.5 text-sm font-semibold text-[var(--green)] shadow-sm"
            onClick={onBack}
            type="button"
          >
            <ChevronLeft size={17} />
            Back to Bible
          </button>
          <div className="text-right">
            <p className="text-xs font-semibold uppercase tracking-[0.14em] text-[var(--muted)]">Passage Guide</p>
            <h1 className="text-lg font-semibold text-[var(--ink)]">{passage}</h1>
          </div>
        </div>
        <nav className="mt-3 flex gap-2 overflow-x-auto pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden" aria-label="Passage guide sections">
          {sections.map(([id, label]) => (
            <a
              key={id}
              className="shrink-0 rounded-full border border-[var(--line)] bg-white px-3 py-1.5 text-xs font-semibold text-[var(--muted)]"
              href={`#${id}`}
            >
              {label}
            </a>
          ))}
        </nav>
      </div>

      <section className="rounded-3xl border border-[var(--line)] bg-white p-5 shadow-sm">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div>
            <p className="text-sm font-semibold uppercase tracking-[0.16em] text-[var(--muted)]">One-scroll chapter study</p>
            <h2 className="mt-2 text-3xl font-semibold tracking-tight text-[var(--ink)]">{passage}</h2>
            <p className="mt-3 max-w-3xl text-sm leading-6 text-[var(--muted)]">{summaryBody}</p>
          </div>
          <div className="flex flex-wrap gap-2">
            {bookIntroduction && (
              <button
                className="inline-flex items-center gap-2 rounded-full border border-[var(--line)] bg-[var(--paper)] px-4 py-2.5 text-sm font-semibold text-[var(--green)]"
                onClick={onOpenBookIntroduction}
                type="button"
              >
                <BookOpen size={16} />
                Book Introduction
              </button>
            )}
            <button
              className="inline-flex items-center gap-2 rounded-full bg-[var(--green)] px-4 py-2.5 text-sm font-semibold text-white"
              disabled={!commentaryEntries.length}
              onClick={onListenCommentary}
              type="button"
            >
              <Headphones size={16} />
              Listen Commentary
            </button>
          </div>
        </div>
        <div className="mt-5 grid grid-cols-2 gap-2 md:grid-cols-4">
          <MiniStat label="Verses" value={String(analysis.stats.verses)} />
          <MiniStat label="Words" value={String(analysis.stats.words)} />
          <MiniStat label="Cross refs" value={String(crossReferences.length)} />
          <MiniStat label="Commentaries" value={String(commentaryAuthors.length)} />
          <MiniStat label="Themes" value={String(activeThemes.length)} />
        </div>
      </section>

      <StudySection id="passage-scorecard" title="Passage Guide Scorecard">
        <div className="grid gap-2 md:grid-cols-3">
          <MiniStat label="Commentary voices" value={String(commentaryAuthors.length)} />
          <MiniStat label="Cross references" value={String(crossReferences.length)} />
          <MiniStat label="Key words" value={String(topWords.length)} />
          <MiniStat label="People" value={String(connections.people.length)} />
          <MiniStat label="Places" value={String(connections.places.length)} />
          <MiniStat label="Resources" value={String(recommendedResources.length)} />
          <MiniStat label="Themes" value={String(activeThemes.length)} />
        </div>
        <div className="mt-4 grid gap-3 lg:grid-cols-2">
          <div className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">Key words</p>
            <div className="mt-2 flex flex-wrap gap-2">
              {topWords.length ? topWords.map((item) => (
                <span key={`scorecard-word-${item.word}`} className="rounded-full bg-white px-3 py-1.5 text-xs font-semibold text-[var(--ink)]">
                  {item.word} <span className="text-[var(--green)]">{item.count}</span>
                </span>
              )) : <span className="text-sm leading-6 text-[var(--muted)]">No key words found yet.</span>}
            </div>
          </div>
          <div className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">Reviewed coverage</p>
            <div className="mt-2 flex flex-wrap gap-2">
              {[
                commentaryEntries.length ? "Commentary ready" : "Commentary pending",
                crossReferences.length ? "Cross references ready" : "Cross references pending",
                connections.people.length ? "People reviewed" : "People pending",
                connections.places.length ? "Places reviewed" : "Places pending",
                passageConnections.length ? "Parallel links ready" : "Parallel links pending",
              ].map((label) => (
                <span key={`scorecard-coverage-${label}`} className="rounded-full bg-white px-3 py-1.5 text-xs font-semibold text-[var(--green)]">
                  {label}
                </span>
              ))}
            </div>
          </div>
        </div>
      </StudySection>

      <StudySection id="passage-start-here" title="Start Here">
        <div className="grid gap-3 lg:grid-cols-5">
          <button
            className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3 text-left"
            onClick={onBack}
            type="button"
          >
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">1. Read</p>
            <p className="mt-1 text-sm font-semibold text-[var(--green)]">Read {passage}</p>
            <p className="mt-2 text-xs leading-5 text-[var(--muted)]">Start with the KJV chapter before opening helps.</p>
          </button>
          <a className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3 text-left" href="#passage-key-verses">
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">2. Key verses</p>
            <p className="mt-1 text-sm font-semibold text-[var(--green)]">{displayKeyVerses[0] ?? passage}</p>
            <p className="mt-2 text-xs leading-5 text-[var(--muted)]">Notice the main verse anchors.</p>
          </a>
          <a className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3 text-left" href="#passage-commentary">
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">3. Commentary</p>
            <p className="mt-1 text-sm font-semibold text-[var(--green)]">{startHereCommentary}</p>
            <p className="mt-2 text-xs leading-5 text-[var(--muted)]">Use commentary after Scripture and references.</p>
          </a>
          <a className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3 text-left" href="#passage-cross-references">
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">4. References</p>
            <p className="mt-1 text-sm font-semibold text-[var(--green)]">{crossReferences.length} reviewed</p>
            <p className="mt-2 text-xs leading-5 text-[var(--muted)]">Let Scripture interpret Scripture.</p>
          </a>
          <a className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3 text-left" href="#passage-resources">
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">5. Resources</p>
            <p className="mt-1 text-sm font-semibold text-[var(--green)]">{startHereResources.length || recommendedResources.length} ready</p>
            <p className="mt-2 text-xs leading-5 text-[var(--muted)]">Open only the best helps for this chapter.</p>
          </a>
        </div>
      </StudySection>

      <StudySection id="passage-best-resources" title="Best Resources">
        <p className="text-sm leading-6 text-[var(--muted)]">
          A short reviewed path for this chapter so users do not have to sort through the full library first.
        </p>
        <div className="mt-3 grid gap-2 md:grid-cols-2 xl:grid-cols-5">
          {([
            ["Best Commentary", bestResources.commentary],
            ["Best Devotional", bestResources.devotional],
            ["Best Study Resource", bestResources.studyBook],
            ["Best Preaching Resource", bestResources.preaching],
            ["Best Next Book", bestResources.nextResource],
          ] as Array<[string, ChapterResourceRecommendation | null]>).map(([label, resource]) => (
            <article key={`passage-best-resource-${label}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
              <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">{label}</p>
              {resource ? (
                <>
                  <p className="mt-2 text-sm font-semibold text-[var(--green)]">{resource.title}</p>
                  {resource.author && <p className="mt-1 text-xs font-semibold text-[var(--muted)]">{resource.author}</p>}
                  <p className="mt-2 line-clamp-4 text-xs leading-5 text-[var(--muted)]">{resource.note}</p>
                  <div className="mt-3 flex flex-wrap gap-2">
                    <span className="rounded-full bg-white px-2.5 py-1 text-xs font-semibold text-[var(--muted)]">{resource.kind}</span>
                    {resource.resourceSlug && (
                      <button
                        className="rounded-full bg-[var(--green)] px-3 py-1.5 text-xs font-semibold text-white"
                        onClick={() => onOpenLibraryResource(resource.resourceSlug!)}
                        type="button"
                      >
                        Open
                      </button>
                    )}
                  </div>
                  {resource.warning && <p className="mt-2 text-xs leading-5 text-[var(--muted)]">{resource.warning}</p>}
                </>
              ) : (
                <p className="mt-2 text-xs leading-5 text-[var(--muted)]">No reviewed resource selected yet.</p>
              )}
            </article>
          ))}
        </div>
      </StudySection>

      <StudySection id="passage-themes" title="Theme Explorer">
        <div className="grid gap-3 lg:grid-cols-[1fr_auto]">
          <div>
            <p className="text-sm leading-6 text-[var(--muted)]">
              These themes connect {passage} to verses, dictionaries, Strong&apos;s starters, commentaries, books, sermon helps, people, places, and timeline entries.
            </p>
            <div className="mt-3 flex flex-wrap gap-2">
              {activeThemes.length ? activeThemes.map((theme) => (
                <span key={`passage-theme-${theme.id}`} className="rounded-full bg-[var(--paper)] px-3 py-1.5 text-xs font-semibold text-[var(--green)]">{theme.title}</span>
              )) : (
                <span className="text-sm leading-6 text-[var(--muted)]">Theme links will appear as this passage is reviewed.</span>
              )}
            </div>
          </div>
          <button className="inline-flex items-center justify-center gap-2 rounded-full bg-[var(--green)] px-4 py-2.5 text-sm font-semibold text-white" onClick={onOpenThemeExplorer} type="button">
            <Brain size={16} />
            Open Theme Explorer
          </button>
        </div>
      </StudySection>

      <StudySection id="passage-study-pack" title="Chapter Study Pack">
        <div className="grid gap-3 lg:grid-cols-[1fr_auto]">
          <div>
            <p className="text-sm leading-6 text-[var(--muted)]">
              A teacher-ready pack for {passage}: theme, outline, commentary highlights, cross references, people, places, timeline, applications, discussion questions, memory verse, and recommended reading.
            </p>
            <div className="mt-3 grid grid-cols-2 gap-2 md:grid-cols-4">
              <MiniStat label="Outline" value={String(bookIntroduction?.outline.length ?? 0)} />
              <MiniStat label="Highlights" value={String(Math.min(5, commentaryEntries.length))} />
              <MiniStat label="Questions" value={String(Math.min(5, 2 + connections.people.length + connections.themes.length))} />
              <MiniStat label="Reading" value={String(recommendedResources.length)} />
            </div>
          </div>
          <div className="flex flex-wrap items-start gap-2 lg:max-w-64">
            <button
              className="inline-flex items-center gap-2 rounded-full bg-[var(--green)] px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50"
              disabled={!chapterStudyPackMarkdown}
              onClick={() => {
                downloadTextFile(`${book.toLowerCase()}-${chapter}-chapter-study-pack.md`, chapterStudyPackMarkdown, "text/markdown;charset=utf-8");
                setPackExportMessage("Chapter Study Pack Markdown downloaded.");
              }}
              type="button"
            >
              <Download size={15} />
              Markdown
            </button>
            <button
              className="inline-flex items-center gap-2 rounded-full border border-[var(--line)] bg-[var(--paper)] px-4 py-2.5 text-sm font-semibold text-[var(--green)] disabled:opacity-50"
              disabled={!chapterStudyPackMarkdown}
              onClick={() => {
                downloadWordCompatibleFile(`${book.toLowerCase()}-${chapter}-chapter-study-pack.docx`, chapterStudyPackMarkdown);
                setPackExportMessage("Word-compatible study pack downloaded.");
              }}
              type="button"
            >
              <FileText size={15} />
              DOCX
            </button>
            <button
              className="inline-flex items-center gap-2 rounded-full border border-[var(--line)] bg-white px-4 py-2.5 text-sm font-semibold text-[var(--muted)]"
              onClick={() => setPackExportMessage("PDF export is coming later. Use Markdown or DOCX for this beta.")}
              type="button"
            >
              <FileText size={15} />
              PDF soon
            </button>
          </div>
        </div>
        {packExportMessage && (
          <p className="mt-3 rounded-2xl border border-[var(--line)] bg-[var(--paper)] px-3 py-2 text-sm leading-6 text-[var(--muted)]">{packExportMessage}</p>
        )}
      </StudySection>

      <StudySection id="passage-background" title="Bible Background Center">
        <BibleBackgroundCenter
          background={background}
          compact
          onOpenReference={onOpenReference}
          onOpenPersonStudy={onOpenPersonStudy}
        />
      </StudySection>

      <StudySection id="passage-culture" title="Culture and Setting">
        <div className="grid gap-3 lg:grid-cols-2">
          <BackgroundList title="Cultural Background" items={background.culturalBackground} empty="No reviewed cultural background is attached yet." />
          <BackgroundList title="Teaching Notes" items={background.teachingNotes} empty="No reviewed background teaching notes are attached yet." />
          <BackgroundList title="Kings" items={background.kings} empty="No king is attached to this chapter." />
          <BackgroundList title="Prophets" items={background.prophets} empty="No prophet is attached to this chapter." />
          <BackgroundList title="Nations" items={background.nations} empty="No nation list is attached yet." />
          <BackgroundList title="Major Events" items={background.majorEvents} empty="No major events are attached yet." />
        </div>
      </StudySection>

      <StudySection id="passage-questions" title="Study Questions">
        <div className="grid gap-2 md:grid-cols-2">
          {studyQuestions.map((question, index) => (
            <article key={`passage-question-${question}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
              <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">Question {index + 1}</p>
              <p className="mt-2 text-sm leading-6 text-[var(--ink)]">{question}</p>
            </article>
          ))}
        </div>
      </StudySection>

      <StudySection id="passage-illustrations" title="Teaching Illustrations">
        <div className="space-y-2">
          {teachingIllustrations.map((prompt) => (
            <p key={`passage-illustration-${prompt}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3 text-sm leading-6 text-[var(--muted)]">
              {prompt}
            </p>
          ))}
        </div>
      </StudySection>

      <StudySection id="passage-commentary-order" title="Recommended Commentary Order">
        {commentaryOrder.length ? (
          <div className="grid gap-2 md:grid-cols-3">
            {commentaryOrder.map((profile, index) => (
              <article key={`passage-commentary-order-${profile.author}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
                <div className="flex flex-wrap items-start justify-between gap-2">
                  <p className="text-sm font-semibold text-[var(--green)]">{index + 1}. {profile.author}</p>
                  <span className="rounded-full bg-white px-2.5 py-1 text-[0.68rem] font-semibold text-[var(--muted)]">{profile.bestFor[0]}</span>
                </div>
                <p className="mt-2 text-xs leading-5 text-[var(--muted)]">{profile.bestUse}</p>
                <p className="mt-2 text-xs leading-5 text-[var(--ink)]">{profile.doctrinalNotes}</p>
              </article>
            ))}
          </div>
        ) : (
          <p className="text-sm leading-6 text-[var(--muted)]">No reviewed commentary order is available for this chapter yet.</p>
        )}
      </StudySection>

      <StudySection id="passage-summary" title="Chapter Summary">
        <div className="space-y-3">
          <p className="text-sm leading-6 text-[var(--scripture-ink)]">{summaryBody}</p>
          {teachingSummary && (
            <div className="grid gap-2 md:grid-cols-3">
              <MiniStat label="Main theme" value={teachingSummary.mainTheme} />
              <MiniStat label="Key verse" value={teachingSummary.keyVerse} />
              <MiniStat label="Aim" value={teachingSummary.teachingAim} />
            </div>
          )}
          {bookIntroduction?.outline.length ? (
            <div className="grid gap-2 md:grid-cols-2">
              {bookIntroduction.outline.slice(0, 4).map((section) => (
                <article key={`passage-outline-preview-${section.reference}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
                  <p className="text-sm font-semibold text-[var(--green)]">{section.title}</p>
                  <p className="mt-1 text-xs font-semibold text-[var(--muted)]">{section.reference}</p>
                  <p className="mt-2 text-xs leading-5 text-[var(--muted)]">{section.summary}</p>
                </article>
              ))}
            </div>
          ) : null}
        </div>
      </StudySection>

      <StudySection id="passage-key-verses" title="Key Verses">
        <div className="space-y-2">
          {displayKeyVerses.map((ref) => {
            const verse = versesByRef.get(ref);
            return (
              <button
                key={`passage-key-${ref}`}
                className="w-full rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3 text-left"
                onClick={() => onOpenReference(ref)}
                type="button"
              >
                <p className="text-sm font-semibold text-[var(--green)]">{ref}</p>
                <p className="mt-2 font-serif text-base leading-7 text-[var(--scripture-ink)]">{verse?.text ?? "KJV verse text not loaded yet."}</p>
              </button>
            );
          })}
        </div>
      </StudySection>

      <StudySection id="passage-repeated-words" title="Repeated Words">
        <div className="grid gap-3 lg:grid-cols-[1fr_1fr]">
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">Words</p>
            <div className="mt-2 flex flex-wrap gap-2">
              {analysis.repeatedWords.length ? analysis.repeatedWords.slice(0, 18).map((item) => (
                <span key={`passage-word-${item.word}`} className="rounded-full border border-[var(--line)] bg-[var(--paper)] px-3 py-1.5 text-xs font-semibold text-[var(--ink)]">
                  {item.word} <span className="text-[var(--green)]">{item.count}</span>
                </span>
              )) : <span className="text-sm leading-6 text-[var(--muted)]">No repeated study words found.</span>}
            </div>
          </div>
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">Phrases</p>
            <div className="mt-2 space-y-2">
              {analysis.repeatedPhrases.length ? analysis.repeatedPhrases.slice(0, 8).map((item) => (
                <p key={`passage-phrase-${item.phrase}`} className="rounded-xl bg-[var(--paper)] px-3 py-2 text-xs font-semibold text-[var(--muted)]">
                  {item.phrase} <span className="text-[var(--green)]">{item.count}</span>
                </p>
              )) : <p className="text-sm leading-6 text-[var(--muted)]">No repeated phrases found yet.</p>}
            </div>
          </div>
        </div>
      </StudySection>

      <StudySection id="passage-word-tools" title={"Webster and Strong's"}>
        <div className="grid gap-3 lg:grid-cols-2">
          <article className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">Webster&apos;s 1828 starter matches</p>
            <div className="mt-3 space-y-2">
              {guideDictionaryEntries.length ? guideDictionaryEntries.map((entry) => (
                <div key={`passage-webster-${entry.lookupWord}`} className="rounded-xl bg-white px-3 py-2">
                  <p className="text-sm font-semibold text-[var(--green)]">{entry.lookupWord}</p>
                  <p className="mt-1 line-clamp-3 text-xs leading-5 text-[var(--muted)]">{entry.definition}</p>
                </div>
              )) : (
                <p className="text-sm leading-6 text-[var(--muted)]">No Webster entries match the repeated words in this chapter yet.</p>
              )}
            </div>
          </article>

          <article className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">Strong&apos;s starter matches</p>
            <div className="mt-3 space-y-2">
              {guideStrongEntries.length ? guideStrongEntries.map((entry) => (
                <div key={`passage-strong-${entry.strongsNumber}`} className="rounded-xl bg-white px-3 py-2">
                  <div className="flex flex-wrap items-center justify-between gap-2">
                    <p className="text-sm font-semibold text-[var(--green)]">{entry.strongsNumber} · {entry.displayWord}</p>
                    <span className="rounded-full bg-[var(--paper)] px-2.5 py-1 text-[0.68rem] font-semibold text-[var(--muted)]">{entry.pronunciation || entry.originalWord}</span>
                  </div>
                  <p className="mt-1 text-xs leading-5 text-[var(--muted)]">{entry.plainMeaning}</p>
                  <p className="mt-1 text-xs font-semibold text-[var(--ink)]">First occurrence: {entry.firstOccurrence}</p>
                </div>
              )) : (
                <p className="text-sm leading-6 text-[var(--muted)]">Strong&apos;s starter matches will appear as reviewed entries are expanded.</p>
              )}
            </div>
          </article>
        </div>
      </StudySection>

      <StudySection id="passage-commentary" title="Commentary Center">
        {commentaryEntries.length ? (
          <div className="space-y-3">
            <div className="grid gap-2 md:grid-cols-2 xl:grid-cols-4">
              {commentaryCenterProfiles.map((item) => (
                <article
                  key={`passage-commentary-center-${item.author}`}
                  className={`rounded-2xl border p-3 ${
                    item.available ? "border-[var(--line)] bg-[var(--paper)]" : "border-dashed border-[var(--line)] bg-white"
                  }`}
                >
                  <div className="flex flex-wrap items-start justify-between gap-2">
                    <p className="text-sm font-semibold text-[var(--green)]">{item.author}</p>
                    <span className={`rounded-full px-2.5 py-1 text-[0.68rem] font-semibold ${
                      item.available ? "bg-white text-[var(--green)]" : "bg-[var(--paper)] text-[var(--muted)]"
                    }`}>
                      {item.available ? `${item.entries} ready` : "Under review"}
                    </span>
                  </div>
                  <p className="mt-2 line-clamp-3 text-xs leading-5 text-[var(--muted)]">
                    {item.profile?.bestUse ?? "Future commentary voice; source, edition, and rights notes must be documented first."}
                  </p>
                </article>
              ))}
            </div>
            <CommentaryChapterSummaryCard entries={commentaryEntries} compact onListen={onListenCommentary} />
            <CommentaryGuideCard entries={commentaryEntries} compact />
            <CommentaryComparisonCard entries={commentaryEntries} compact />
            <article className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div>
                  <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">Commentary Consensus</p>
                  <h4 className="mt-1 text-sm font-semibold text-[var(--ink)]">Compare after reading the KJV text</h4>
                </div>
                <span className="rounded-full bg-white px-2.5 py-1 text-xs font-semibold text-[var(--green)]">
                  {commentaryAuthors.length} voices
                </span>
              </div>
              <div className="mt-3 grid gap-2 md:grid-cols-3">
                <ComparisonInsight label="Agreement points" body={commentaryConsensus.agreement} />
                <ComparisonInsight label="Distinct insights" body={commentaryConsensus.distinct} />
                <ComparisonInsight label="Teaching observations" body={commentaryConsensus.teaching} />
              </div>
              {commentaryConsensus.study && (
                <p className="mt-3 rounded-xl bg-white px-3 py-2 text-xs leading-5 text-[var(--muted)]">{commentaryConsensus.study}</p>
              )}
            </article>
            <div className="flex flex-wrap gap-2">
              <button
                className="inline-flex items-center gap-2 rounded-full border border-[var(--line)] bg-[var(--paper)] px-3 py-2 text-xs font-semibold text-[var(--green)]"
                onClick={onAddCommentaryToPlaylist}
                type="button"
              >
                <ListMusic size={14} />
                Add Commentary to Playlist
              </button>
            </div>
            <div className="space-y-2">
              {commentaryEntries.slice(0, 6).map((entry) => (
                <CommentaryDetails key={`passage-commentary-${entry.id}`} entry={entry} compact />
              ))}
            </div>
            <details className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
              <summary className="cursor-pointer text-sm font-semibold text-[var(--green)]">Content growth priority</summary>
              <div className="mt-3 grid gap-2 md:grid-cols-2">
                {[...PASSAGE_GUIDE_COMMENTARY_GROWTH].sort((a, b) => commentaryGrowthPriority(a) - commentaryGrowthPriority(b)).map((item) => (
                  <article key={`commentary-growth-${item.author}`} className="rounded-xl bg-white p-3">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <p className="text-sm font-semibold text-[var(--ink)]">{item.author}</p>
                      <span className="rounded-full bg-[var(--paper)] px-2.5 py-1 text-[0.68rem] font-semibold text-[var(--green)]">
                        {commentaryGrowthStatusLabel(item.status)}
                      </span>
                    </div>
                    <p className="mt-2 text-xs leading-5 text-[var(--muted)]">{item.focus}</p>
                    <p className="mt-2 text-xs leading-5 text-[var(--ink)]">Next: {item.nextStep}</p>
                    <p className="mt-1 text-xs leading-5 text-[var(--muted)]">{item.caution}</p>
                  </article>
                ))}
              </div>
            </details>
          </div>
        ) : (
          <p className="text-sm leading-6 text-[var(--muted)]">No reviewed commentary entries yet.</p>
        )}
      </StudySection>

      <StudySection id="passage-parallels" title="Parallel Passage Guide">
        <div className="grid gap-2 md:grid-cols-3">
          {(["Gospel Parallel", "Acts Connection", "Prophecy Fulfillment"] as PassageGuideConnectionKind[]).map((kind) => {
            const matches = passageConnections.filter((connection) => connection.kind === kind);
            return (
              <article key={`parallel-kind-${kind}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">{kind}</p>
                  <span className="rounded-full bg-white px-2 py-1 text-[0.68rem] font-semibold text-[var(--green)]">{matches.length}</span>
                </div>
                <div className="mt-3 space-y-2">
                  {matches.length ? matches.map((connection) => (
                    <div key={`parallel-${connection.kind}-${connection.title}`} className="rounded-xl bg-white p-3">
                      <p className="text-sm font-semibold text-[var(--green)]">{connection.title}</p>
                      <p className="mt-1 text-xs leading-5 text-[var(--muted)]">{connection.note}</p>
                      <ReferenceRow references={connection.references} onOpenReference={onOpenReference} />
                    </div>
                  )) : (
                    <p className="text-sm leading-6 text-[var(--muted)]">No reviewed {kind.toLowerCase()} links yet.</p>
                  )}
                </div>
              </article>
            );
          })}
        </div>
      </StudySection>

      <StudySection id="passage-cross-references" title="Cross References">
        <div className="grid gap-2 md:grid-cols-2">
          {visibleCrossReferences.length ? visibleCrossReferences.map((reference) => {
            const preview = versesByRef.get(reference.target_ref)?.text;
            return (
              <button
                key={`passage-cross-${reference.id}`}
                className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3 text-left"
                onClick={() => onOpenReference(reference.target_ref)}
                type="button"
              >
                <div className="flex items-center justify-between gap-3">
                  <p className="text-sm font-semibold text-[var(--green)]">{reference.target_ref}</p>
                  <span className="rounded-full bg-white px-2.5 py-1 text-xs font-semibold text-[var(--muted)]">{reference.source}</span>
                </div>
                <p className="mt-2 line-clamp-3 font-serif text-sm leading-6 text-[var(--scripture-ink)]">{preview ?? reference.label}</p>
              </button>
            );
          }) : <p className="text-sm leading-6 text-[var(--muted)]">No reviewed cross references yet.</p>}
        </div>
      </StudySection>

      <StudySection id="passage-people" title="People">
        <div className="grid gap-2 md:grid-cols-2">
          {connections.people.length ? connections.people.map((person) => (
            <button
              key={`passage-person-${person.id}`}
              className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3 text-left"
              onClick={() => onOpenPersonStudy(person.id)}
              type="button"
            >
              <p className="text-sm font-semibold text-[var(--green)]">{person.name}</p>
              <p className="mt-2 text-xs leading-5 text-[var(--muted)]">{person.summary}</p>
              <p className="mt-2 text-xs font-semibold text-[var(--ink)]">First appearance: {person.firstAppearance}</p>
            </button>
          )) : <p className="text-sm leading-6 text-[var(--muted)]">No reviewed people entries yet.</p>}
        </div>
      </StudySection>

      <StudySection id="passage-places" title="Places">
        <div className="grid gap-2 md:grid-cols-2">
          {connections.places.length ? connections.places.map((place) => (
            <PlaceContextCard key={`passage-place-${place.id}`} place={place} onOpenReference={onOpenReference} />
          )) : <p className="text-sm leading-6 text-[var(--muted)]">No reviewed place entries yet.</p>}
        </div>
      </StudySection>

      <StudySection id="passage-timeline" title="Timeline">
        <div className="grid gap-2 md:grid-cols-2">
          {connections.timeline.length ? connections.timeline.map((entry) => (
            <TimelineContextCard key={`passage-timeline-${entry.id}`} entry={entry} onOpenReference={onOpenReference} />
          )) : <p className="text-sm leading-6 text-[var(--muted)]">No reviewed timeline entries yet.</p>}
        </div>
      </StudySection>

      <StudySection id="passage-types" title="Types of Christ">
        <div className="space-y-2">
          {connections.types.length ? connections.types.map((type) => (
            <article key={`passage-type-${type.id}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
              <p className="text-sm font-semibold text-[var(--green)]">{type.title}</p>
              <p className="mt-2 text-xs leading-5 text-[var(--muted)]">{type.description}</p>
              <p className="mt-2 text-xs leading-5 text-[var(--ink)]">{type.pointsToChrist}</p>
              <ReferenceRow references={[...type.keyReferences, ...type.fulfillmentReferences]} onOpenReference={onOpenReference} />
            </article>
          )) : <p className="text-sm leading-6 text-[var(--muted)]">No reviewed type of Christ entry yet.</p>}
        </div>
      </StudySection>

      <StudySection id="passage-prophecies" title="Prophecy Connections">
        <div className="space-y-2">
          {connections.prophecies.length ? connections.prophecies.map((prophecy) => (
            <article key={`passage-prophecy-${prophecy.id}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
              <p className="text-sm font-semibold text-[var(--green)]">{prophecy.prophecy} <span className="text-[var(--muted)]">to</span> {prophecy.fulfillment}</p>
              <p className="mt-2 text-xs leading-5 text-[var(--muted)]">{prophecy.description}</p>
              <ReferenceRow references={prophecy.relatedVerses} onOpenReference={onOpenReference} />
            </article>
          )) : <p className="text-sm leading-6 text-[var(--muted)]">No reviewed prophecy connection yet.</p>}
        </div>
      </StudySection>

      <StudySection id="passage-related-books" title="Related Books">
        {relatedBooks.length ? (
          <div className="grid gap-2 md:grid-cols-2">
            {relatedBooks.map(({ recommendation, resource }) => (
              <article key={`passage-related-book-${resource.slug}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
                <div className="flex flex-wrap items-start justify-between gap-2">
                  <div>
                    <p className="text-sm font-semibold text-[var(--green)]">{resource.title}</p>
                    <p className="mt-1 text-xs font-semibold text-[var(--muted)]">{resource.author}</p>
                  </div>
                  <span className="rounded-full bg-white px-2.5 py-1 text-xs font-semibold text-[var(--muted)]">{libraryCategoryLabel(resource.category)}</span>
                </div>
                <p className="mt-2 line-clamp-3 text-xs leading-5 text-[var(--muted)]">{recommendation.note || resource.description}</p>
                <div className="mt-3 flex flex-wrap items-center gap-2">
                  <button
                    className="rounded-full bg-[var(--green)] px-3 py-1.5 text-xs font-semibold text-white"
                    onClick={() => onOpenLibraryResource(resource.slug)}
                    type="button"
                  >
                    Open Book
                  </button>
                  <span className="text-xs font-semibold text-[var(--muted)]">{libraryReadingMinutes(resource)}</span>
                </div>
              </article>
            ))}
          </div>
        ) : (
          <p className="text-sm leading-6 text-[var(--muted)]">No related library books are linked to this chapter yet.</p>
        )}
      </StudySection>

      <StudySection id="passage-sermons" title="Related Sermons">
        <div className="rounded-2xl border border-dashed border-[var(--line)] bg-[var(--paper)] p-4">
          <p className="text-sm font-semibold text-[var(--green)]">Sermon resources coming soon</p>
          <p className="mt-2 text-sm leading-6 text-[var(--muted)]">
            Sermon audio, transcripts, and teaching series can be attached here later when they are ready for public use.
          </p>
        </div>
      </StudySection>

      <StudySection id="passage-resources" title="Recommended Resources">
        <div className="grid gap-2 md:grid-cols-2">
          {recommendedResources.length ? recommendedResources.map((resource) => {
            const libraryResource = resource.resourceSlug ? libraryResources.find((candidate) => candidate.slug === resource.resourceSlug) : null;
            return (
              <article key={`passage-resource-${resource.id}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
                <div className="flex flex-wrap items-start justify-between gap-2">
                  <div>
                    <p className="text-xs font-semibold uppercase tracking-[0.12em] text-[var(--muted)]">{resource.kind}</p>
                    <p className="mt-1 text-sm font-semibold text-[var(--green)]">{resource.title}</p>
                    {resource.author && <p className="mt-1 text-xs font-semibold text-[var(--muted)]">{resource.author}</p>}
                  </div>
                  <span className="rounded-full bg-white px-2.5 py-1 text-xs font-semibold capitalize text-[var(--muted)]">{chapterResourceStatusLabel(resource.status)}</span>
                </div>
                <p className="mt-2 text-xs leading-5 text-[var(--muted)]">{resource.note}</p>
                {libraryResource?.word_count ? (
                  <p className="mt-2 text-xs font-semibold text-[var(--green)]">{Math.max(1, Math.round(libraryResource.word_count / 220))} min read</p>
                ) : null}
                <div className="mt-3 flex flex-wrap gap-2">
                  {resource.resourceSlug && (
                    <button
                      className="rounded-full bg-[var(--green)] px-3 py-1.5 text-xs font-semibold text-white"
                      onClick={() => onOpenLibraryResource(resource.resourceSlug!)}
                      type="button"
                    >
                      Open Resource
                    </button>
                  )}
                  {resource.warning && (
                    <span className="rounded-full bg-[var(--highlight)] px-3 py-1.5 text-xs font-semibold text-[var(--ink)]">
                      {resource.warning}
                    </span>
                  )}
                </div>
              </article>
            );
          }) : <p className="text-sm leading-6 text-[var(--muted)]">No recommended resources yet.</p>}
        </div>
      </StudySection>

      <StudySection id="passage-outline" title="Teaching Outline">
        <p className="text-sm leading-6 text-[var(--muted)]">
          Built from reviewed/stored study data already in the app. No doctrine is generated automatically.
        </p>
        <div className="mt-3 grid gap-3 md:grid-cols-2">
          {lessonOutlineSections.length ? lessonOutlineSections.map((section) => (
            <section key={`passage-lesson-${section.title}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
              <h4 className="text-sm font-semibold text-[var(--green)]">{section.title}</h4>
              <ul className="mt-2 space-y-1 text-xs leading-5 text-[var(--muted)]">
                {sectionOrEmpty(section.lines).slice(0, 5).map((line) => (
                  <li key={`passage-lesson-${section.title}-${line}`}>{line}</li>
                ))}
              </ul>
            </section>
          )) : <p className="text-sm leading-6 text-[var(--muted)]">No reviewed outline data yet.</p>}
        </div>
      </StudySection>
    </div>
  );
}

function FullStudyScreen({
  verse,
  keyWords,
  crossReferences,
  commentaryEntries,
  connections,
  versesByRef,
  existingNote,
  highlighted,
  bookmarked,
  memoryItem,
  noteDraft,
  syncMessage,
  onBack,
  onNoteDraftChange,
  onSaveNote,
  onHighlight,
  onBookmark,
  onOpenReference,
  onListenCommentary,
  onAddCommentaryToPlaylist,
  onAddMemory,
  onUpdateMemoryProgress,
  onRemoveMemory,
}: {
  verse: BibleVerse;
  keyWords: string[];
  crossReferences: CrossReference[];
  commentaryEntries: CommentaryEntry[];
  connections: ActiveChapterConnections;
  versesByRef: Map<string, BibleVerse>;
  existingNote: UserNote | null;
  highlighted: boolean;
  bookmarked: boolean;
  noteDraft: string;
  syncMessage: string;
  memoryItem: ScriptureMemoryItem | null;
  onBack: () => void;
  onNoteDraftChange: (value: string) => void;
  onSaveNote: () => void;
  onHighlight: () => void;
  onBookmark: () => void;
  onOpenReference: (targetRef: string) => void;
  onListenCommentary: () => void;
  onAddCommentaryToPlaylist: () => void;
  onAddMemory: () => void;
  onUpdateMemoryProgress: (progress: number) => void;
  onRemoveMemory: () => void;
}) {
  const [commentaryAuthorFilter, setCommentaryAuthorFilter] = useState("All");
  const definitions = keyWords
    .map((word) => findDictionaryEntry(word))
    .filter((entry) => entry.found);
  const commentaryAuthorOptions = ["All", ...Array.from(new Set(commentaryEntries.map((entry) => entry.author))).sort()];
  const effectiveCommentaryAuthorFilter = commentaryAuthorOptions.includes(commentaryAuthorFilter) ? commentaryAuthorFilter : "All";
  const displayedCommentaryEntries = effectiveCommentaryAuthorFilter === "All"
    ? commentaryEntries
    : commentaryEntries.filter((entry) => entry.author === effectiveCommentaryAuthorFilter);
  const firstDefinition = definitions[0] ?? null;
  const sections = [
    { id: "full-study-verse", label: "Verse" },
    { id: "full-study-key-words", label: "Key Words" },
    { id: "full-study-cross-references", label: "Cross References" },
    { id: "full-study-atlas-timeline", label: "Atlas & Timeline" },
    { id: "full-study-my-study", label: "My Study" },
    { id: "full-study-commentary", label: "Commentary" },
    { id: "full-study-memory", label: "Memory" },
  ];

  return (
    <div className="space-y-4 p-4 pb-36 md:p-8 md:pb-10">
      <div className="sticky top-[104px] z-10 -mx-4 border-b border-[var(--line)] bg-[var(--paper)]/95 px-4 pb-3 pt-2 backdrop-blur md:top-0 md:mx-0 md:rounded-2xl md:border md:px-4">
        <div className="flex items-center justify-between gap-3">
          <button
            className="inline-flex items-center gap-2 rounded-full border border-[var(--line)] bg-white px-4 py-2.5 text-sm font-semibold text-[var(--green)] shadow-sm"
            onClick={onBack}
            type="button"
          >
            <ChevronLeft size={17} />
            Back to Bible
          </button>
          <p className="rounded-full border border-[var(--line)] bg-white px-3 py-1.5 text-xs font-semibold text-[var(--muted)]">
            Mini Passage Guide
          </p>
        </div>
        <nav className="mt-3 flex gap-2 overflow-x-auto pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden" aria-label="Full study sections">
          {sections.map((section) => (
            <a
              key={section.id}
              className="shrink-0 rounded-full border border-[var(--line)] bg-white px-3 py-1.5 text-xs font-semibold text-[var(--muted)]"
              href={`#${section.id}`}
            >
              {section.label}
            </a>
          ))}
        </nav>
      </div>

      <StudySection id="full-study-verse" title="Verse">
        <p className="text-sm font-semibold text-[var(--green)]">{verse.ref}</p>
        <p className="mt-2 font-serif text-xl leading-9 text-[var(--scripture-ink)] md:text-2xl md:leading-10">{verse.text}</p>
      </StudySection>

      <StudySection id="full-study-key-words" title="Key Words">
        <div className="flex flex-wrap gap-2">
          {keyWords.map((word) => (
            <span
              key={`full-keyword-${word}`}
              className="rounded-full border border-[var(--line)] bg-[var(--paper)] px-3 py-1.5 text-sm font-semibold text-[var(--ink)]"
            >
              {word}
            </span>
          ))}
        </div>

        {definitions.length ? (
          <div className="mt-4 space-y-3">
            {definitions.map((entry) => (
              <article key={`definition-${entry.lookupWord}`} className="rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <h4 className="text-base font-semibold capitalize text-[var(--ink)]">{entry.word}</h4>
                  <span className="rounded-full bg-white px-2.5 py-1 text-xs font-semibold text-[var(--green)]">Webster&apos;s 1828</span>
                </div>
                {entry.lookupWord !== entry.word && (
                  <p className="mt-1 text-xs font-semibold text-[var(--muted)]">Normalized to: {entry.lookupWord}</p>
                )}
                <p className="mt-2 text-sm leading-6 text-[var(--scripture-ink)]">{entry.definition}</p>
              </article>
            ))}
          </div>
        ) : (
          <p className="mt-3 text-sm leading-6 text-[var(--muted)]">No Webster&apos;s definitions are loaded for these words yet.</p>
        )}
        {firstDefinition && (
          <div className="mt-4 grid grid-cols-3 gap-2">
            <MiniStat label="Lookup" value={firstDefinition.lookupWord} />
            <MiniStat label="Source" value="1828" />
            <MiniStat label="Ready" value={firstDefinition.found ? "Yes" : "Soon"} />
          </div>
        )}
      </StudySection>

      <StudySection id="full-study-cross-references" title="Cross References">
        {crossReferences.length ? (
          <div className="space-y-2">
            {crossReferences.map((reference) => {
              const preview = versesByRef.get(reference.target_ref)?.text;
              return (
                <button
                  key={`full-cross-reference-${reference.id}`}
                  className="w-full rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3 text-left"
                  onClick={() => onOpenReference(reference.target_ref)}
                  type="button"
                >
                  <div className="flex items-center justify-between gap-3">
                    <p className="text-sm font-semibold text-[var(--green)]">{reference.target_ref}</p>
                    <p className="rounded-full bg-white px-2.5 py-1 text-xs font-semibold text-[var(--muted)]">{reference.source}</p>
                  </div>
                  <p className="mt-2 line-clamp-3 font-serif text-sm leading-6 text-[var(--scripture-ink)]">
                    {preview ?? reference.label}
                  </p>
                  {reference.source_title && (
                    <p className="mt-2 text-xs font-semibold text-[var(--muted)]">{reference.source_title}</p>
                  )}
                </button>
              );
            })}
          </div>
        ) : (
          <p className="text-sm leading-6 text-[var(--muted)]">No cross references are loaded for this verse yet.</p>
        )}
      </StudySection>

      <StudySection id="full-study-atlas-timeline" title="Atlas & Timeline">
        <div className="grid gap-3 lg:grid-cols-2">
          <div>
            <div className="flex items-center gap-2 text-[var(--green)]">
              <MapPin size={17} />
              <h4 className="text-sm font-semibold">Places</h4>
            </div>
            <div className="mt-3 space-y-2">
              {connections.places.length ? connections.places.map((place) => (
                <PlaceContextCard key={`full-study-place-${place.id}`} place={place} onOpenReference={onOpenReference} />
              )) : (
                <p className="text-sm leading-6 text-[var(--muted)]">No reviewed atlas entries are attached to this chapter yet.</p>
              )}
            </div>
          </div>
          <div>
            <div className="flex items-center gap-2 text-[var(--green)]">
              <Timer size={17} />
              <h4 className="text-sm font-semibold">Timeline</h4>
            </div>
            <div className="mt-3 space-y-2">
              {connections.timeline.length ? connections.timeline.map((entry) => (
                <TimelineContextCard key={`full-study-timeline-${entry.id}`} entry={entry} onOpenReference={onOpenReference} />
              )) : (
                <p className="text-sm leading-6 text-[var(--muted)]">No reviewed timeline entries are attached to this chapter yet.</p>
              )}
            </div>
          </div>
        </div>
      </StudySection>

      <StudySection id="full-study-my-study" title="My Study">
        <div className="grid grid-cols-2 gap-2">
          <CompactActionButton active={highlighted} icon={<Highlighter size={17} />} label={highlighted ? "Highlighted" : "Highlight"} onClick={onHighlight} />
          <CompactActionButton active={bookmarked} icon={<Bookmark size={17} />} label={bookmarked ? "Bookmarked" : "Bookmark"} onClick={onBookmark} />
        </div>
        <label className="mt-4 block text-sm font-semibold text-[var(--muted)]">
          Personal note
          <textarea
            className="mt-2 min-h-32 w-full rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3 text-base leading-6 outline-none"
            placeholder="Write a note for this verse..."
            value={noteDraft}
            onChange={(event) => onNoteDraftChange(event.target.value)}
          />
        </label>
        <button className="mt-3 rounded-full bg-[var(--green)] px-5 py-3 text-sm font-semibold text-white" onClick={onSaveNote} type="button">
          {existingNote ? "Update note" : "Save note"}
        </button>
        {syncMessage && <p className="mt-3 text-sm leading-6 text-[var(--muted)]">{syncMessage}</p>}
      </StudySection>

      <StudySection id="full-study-commentary" title="Commentary">
        {commentaryEntries.length ? (
          <div className="space-y-3">
            <CommentaryChapterSummaryCard entries={commentaryEntries} onListen={onListenCommentary} />
            <CommentaryGuideCard entries={commentaryEntries} />
            <CommentaryComparisonCard entries={commentaryEntries} />
            <div className="flex flex-wrap items-center justify-between gap-2 rounded-2xl border border-[var(--line)] bg-[var(--paper)] p-3">
              <div>
                <p className="text-sm font-semibold text-[var(--green)]">Commentary comparison</p>
                <p className="mt-1 text-xs leading-5 text-[var(--muted)]">{commentaryAgreementSummary(commentaryEntries)}</p>
              </div>
              <div className="flex flex-wrap gap-2">
                {commentaryAuthorOptions.length > 2 && (
                  <select
                    className="rounded-full border border-[var(--line)] bg-white px-3 py-2 text-xs font-semibold text-[var(--green)] outline-none"
                    value={effectiveCommentaryAuthorFilter}
                    onChange={(event) => setCommentaryAuthorFilter(event.target.value)}
                  >
                    {commentaryAuthorOptions.map((author) => (
                      <option key={`full-commentary-author-${author}`} value={author}>{author}</option>
                    ))}
                  </select>
                )}
                <button
                  className="inline-flex items-center gap-2 rounded-full bg-white px-3 py-2 text-xs font-semibold text-[var(--green)]"
                  onClick={onListenCommentary}
                  type="button"
                >
                  <Headphones size={14} />
                  Listen
                </button>
                <button
                  className="inline-flex items-center gap-2 rounded-full bg-white px-3 py-2 text-xs font-semibold text-[var(--green)]"
                  onClick={onAddCommentaryToPlaylist}
                  type="button"
                >
                  <ListMusic size={14} />
                  Add to Study Playlist
                </button>
              </div>
            </div>
            {displayedCommentaryEntries.map((entry) => (
              <CommentaryDetails key={`full-commentary-${entry.id}`} entry={entry} />
            ))}
          </div>
        ) : (
          <p className="text-sm leading-6 text-[var(--muted)]">Commentary resources will appear here after verified public-domain content is imported.</p>
        )}
      </StudySection>

      <StudySection id="full-study-memory" title="Memory">
        <MemoryReviewCard
          item={memoryItem}
          fallbackVerse={verse}
          onAddMemoryVerse={() => onAddMemory()}
          onRemoveMemoryVerse={() => onRemoveMemory()}
          onUpdateMemoryProgress={(_ref, progress) => onUpdateMemoryProgress(progress)}
        />
      </StudySection>
    </div>
  );
}

